-- desAnim8 single-file build. GENERATED by tools/bundle.lua from desAnim8.lua and
-- desAnim8/*.lua: edit those files and rebuild, never this one.
-- Requires nothing: modules are packed below and found by a private require.

local __modules, __loaded = {}, {}

local function require(name)
    local cached = __loaded[name]
    if cached ~= nil then return cached end
    local loader = __modules[name]
    if loader == nil then error("desAnim8 bundle: no module '" .. name .. "'", 2) end
    local result = loader(name)
    if result == nil then result = true end
    __loaded[name] = result
    return result
end

__modules['desAnim8.util'] = function(...)
-- Small helpers shared by every module. Internal: not part of the public API.
-- `level` arguments follow error(): the number of stack frames from the raising
-- function up to the user's call, so messages point at user code.

-- `level` arguments below follow error(): the number of stack frames from the
-- raising function up to the user's call, so messages point at user code.

local function assertPositiveInteger(value, name, level)
    if type(value) ~= 'number' or value < 1 or value == math.huge or value ~= math.floor(value) then
        error(('%s must be a positive integer, got %s'):format(name, tostring(value)), level)
    end
end

local function assertNonNegativeInteger(value, name, level)
    if type(value) ~= 'number' or value < 0 or value == math.huge or value ~= math.floor(value) then
        error(('%s must be a non-negative integer, got %s'):format(name, tostring(value)), level)
    end
end

-- Binary search: find i such that intervals[i] <= t < intervals[i+1].
-- Correctly returns the last index when t == totalDuration.
local function seekIndex(intervals, t)
    local low, high, i = 1, #intervals - 1, 1
    while low <= high do
        i = math.floor((low + high) / 2)
        if     t >= intervals[i + 1] then low  = i + 1
        elseif t <  intervals[i]     then high = i - 1
        else   break
        end
    end
    return i
end

-- Returns (from, to, step) with no table allocation.
-- Accepts a number, a "n" string, or a "n-m" range string (spaces ignored).
-- `what` names the argument in error messages.
local function parseRange(v, max, level, what)
    if v == nil then
        error(('missing %s argument: ranges come in (columns, rows) pairs'):format(what), level)
    end
    local a, b
    if type(v) == 'number' then
        if v ~= math.floor(v) then
            error(('%s must be an integer, got %s'):format(what, tostring(v)), level)
        end
        a, b = v, v
    else
        local s = tostring(v):gsub('%s+', '')
        local x, y = s:match('^(%d+)-(%d+)$')
        if x then
            a, b = tonumber(x), tonumber(y)
        else
            a = tonumber(s:match('^(%d+)$'))
            b = a
        end
        if not a then
            error(('invalid %s %q, expected a number or "n-m"'):format(what, tostring(v)), level)
        end
    end
    if a < 1 or a > max or b < 1 or b > max then
        error(('%s %s out of range [1,%d]'):format(what, tostring(v), max), level)
    end
    return a, b, a <= b and 1 or -1
end

local function isInteger(v)
    return type(v) == 'number' and v == math.floor(v) and v > -math.huge and v < math.huge
end

local function flipFor(dx, facing) return dx * facing < 0 end

return {
    assertPositiveInteger    = assertPositiveInteger,
    assertNonNegativeInteger = assertNonNegativeInteger,
    seekIndex                = seekIndex,
    parseRange               = parseRange,
    isInteger                = isInteger,
    flipFor                  = flipFor,
}
end

__modules['desAnim8.timing'] = function(...)
-- Timing model: durations, play-mode sequences, the wrap region, easing and
-- the helpers that turn a timer into a frame. Internal: not part of the public API.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local parseRange, seekIndex = util.parseRange, util.seekIndex

local function assertDuration(dur, what, level)
    if type(dur) ~= 'number' or not (dur > 0) or dur == math.huge then
        error(('%s must be a positive number, got %s'):format(what, tostring(dur)), level)
    end
end

-- durations can be:
--   number              -> same duration for every frame
--   {d1, d2, ...}       -> per-frame array
--   {['2-4'] = 0.2, ..} -> range-keyed table
local function parseDurations(durations, frameCount, level)
    if type(durations) == 'number' then
        assertDuration(durations, 'frameDuration', level + 1)
        local t = {}
        for i = 1, frameCount do t[i] = durations end
        return t
    end
    if type(durations) ~= 'table' then
        error('durations must be a positive number or a table', level)
    end
    local result = {}
    for key, dur in pairs(durations) do
        assertDuration(dur, ('duration for key %q'):format(tostring(key)), level + 1)
        local from, to, step = parseRange(key, frameCount, level + 1, 'durations key')
        for k = from, to, step do
            if result[k] then
                error(('durations: frame %d is assigned more than once (key %q)'):format(k, tostring(key)), level)
            end
            result[k] = dur
        end
    end
    for i = 1, frameCount do
        if not result[i] then error(('no duration specified for frame %d'):format(i), level) end
    end
    return result
end

local function buildIntervals(durations)
    local t, intervals = 0, { 0 }
    for i = 1, #durations do
        t = t + durations[i]
        intervals[i + 1] = t
    end
    return intervals, t
end

local VALID_MODES  = { loop=true, once=true, bounce=true, bounceOnce=true, random=true }
local PAUSE_AT_END = { once=true, bounceOnce=true }
local MODE_LIST    = "'loop', 'once', 'bounce', 'bounceOnce' or 'random'"

local DEFAULT_RANDOM_LENGTH = 32

-- Expand play mode into a flat sequence of frame indices:
--   loop/once      -> [1, 2, ..., n]
--   bounce         -> [1, 2, ..., n, n-1, ..., 2]   endpoints appear once
--   bounceOnce     -> [1, 2, ..., n, n-1, ..., 1]
local function buildSequence(n, playMode)
    if n == 1 then return { 1 } end
    local seq = {}
    if playMode == 'loop' or playMode == 'once' then
        for i = 1, n do seq[i] = i end
    elseif playMode == 'bounce' then
        for i = 1, n         do seq[#seq + 1] = i end
        for i = n - 1, 2, -1 do seq[#seq + 1] = i end
    else -- bounceOnce
        for i = 1, n         do seq[#seq + 1] = i end
        for i = n - 1, 1, -1 do seq[#seq + 1] = i end
    end
    return seq
end

-- Weighted pick of a frame index, skipping up to two excluded frames.
local function pickRandom(n, weights, rng, skipA, skipB)
    local total = 0
    for i = 1, n do
        if i ~= skipA and i ~= skipB then total = total + (weights and weights[i] or 1) end
    end
    if total <= 0 then return nil end
    local r, last = rng() * total, nil
    for i = 1, n do
        if i ~= skipA and i ~= skipB then
            local w = weights and weights[i] or 1
            if w > 0 then
                last = i
                r = r - w
                if r < 0 then return i end
            end
        end
    end
    return last
end

-- A fixed random order generated up front, so the regular sequence machinery
-- (intervals, events, state) works unchanged. No frame repeats back to back,
-- including across the wrap, when the weights allow it.
local function buildRandomSequence(n, length, weights, rng)
    if n == 1 then return { 1 } end
    local seq = { pickRandom(n, weights, rng) }
    for i = 2, length do
        local frame
        if i == length then frame = pickRandom(n, weights, rng, seq[i - 1], seq[1]) end
        seq[i] = frame or pickRandom(n, weights, rng, seq[i - 1])
    end
    return seq
end

-- Loop range support: playback wraps inside [_wrapStart, _wrapEnd], which is the
-- whole sequence unless setLoopRange narrowed it and release() has not been called.
local function applyRegion(self)
    self._plain = nil
    local from, to = self._loopFrom, self._loopTo
    if from and not self._released then
        self._wrapStart, self._wrapEnd = self._intervals[from], self._intervals[to + 1]
        self._wrapFirst, self._wrapLast = from, to
    else
        self._wrapStart, self._wrapEnd = 0, self._totalDuration
        self._wrapFirst, self._wrapLast = 1, #self._seq
    end
end

-- Installs a sequence and derives intervals from the durations. Always assigns
-- new tables, because clones may still share the old ones.
local function applySequence(self, seq)
    local seqDur = {}
    for i, fi in ipairs(seq) do seqDur[i] = self._durations[fi] end
    local intervals, total = buildIntervals(seqDur)
    self._seq           = seq
    self._intervals     = intervals
    self._totalDuration = total
    applyRegion(self)
end

local function applyTiming(self)
    local seq
    if self.playMode == 'random' then
        local o = self._opts
        seq = buildRandomSequence(#self.frames, o.randomLength or DEFAULT_RANDOM_LENGTH,
            o.weights, o.rng or math.random)
    else
        seq = buildSequence(#self.frames, self.playMode)
    end
    applySequence(self, seq)
end

local function initTiming(self)
    applyTiming(self)
    self._timer       = 0
    self._position    = 1
    self._loops       = 0
    self._freeze      = 0
    self._started     = false
    self._released    = false
    applyRegion(self)
    self.currentFrame = self._seq[1]
    self.status       = 'playing'
end

-- Time as seen by the frame lookup: eased and quantized when configured.
local function displayTime(self)
    local t, total = self._timer, self._totalDuration
    local ease = self._ease
    if ease then t = ease(t / total) * total end
    local step = self._step
    if step then t = math.floor(t / step + 1e-9) * step end
    return t
end

-- Recomputes position and frame from the timer. The end of the sequence is a
-- sentinel (timer == total) that always shows the last entry.
local function locate(self)
    if self._timer >= self._totalDuration then
        self._position = #self._seq
    else
        self._position = seekIndex(self._intervals, displayTime(self))
    end
    self.currentFrame = self._seq[self._position]
end

-- Timer whose eased display time reaches `target`: the inverse of the easing,
-- found by bisection, which works because easings never decrease.
local function timerForDisplay(self, target)
    local ease, total = self._ease, self._totalDuration
    if not ease or target <= 0 then return target end
    if target >= total then return total end
    local lo, hi = 0, total
    for _ = 1, 50 do
        local mid = (lo + hi) / 2
        if ease(mid / total) * total >= target then hi = mid else lo = mid end
    end
    return hi
end

-- Timer that displays sequence `position`: its start time, nudged to the first
-- instant the step lets through and mapped back through the easing.
local function timerFor(self, position)
    local intervals = self._intervals
    local target = intervals[position]
    local step = self._step
    if step then
        -- a frame shorter than the step may have no displayable instant, in which
        -- case its start time is kept
        local snapped = math.ceil(target / step - 1e-9) * step
        if snapped < intervals[position + 1] then target = snapped end
    end
    return timerForDisplay(self, target)
end

local EASINGS = {
    linear     = function(t) return t end,
    inQuad     = function(t) return t * t end,
    outQuad    = function(t) return t * (2 - t) end,
    inOutQuad  = function(t) return t < 0.5 and 2 * t * t or 1 - (2 - 2 * t) ^ 2 / 2 end,
    inCubic    = function(t) return t * t * t end,
    outCubic   = function(t) return 1 - (1 - t) ^ 3 end,
    inOutCubic = function(t) return t < 0.5 and 4 * t * t * t or 1 - (2 - 2 * t) ^ 3 / 2 end,
}

-- Validated easing function for a name, a user function or nil (-> nil).
local function resolveEasing(easing, what, level)
    if easing == nil then return nil end
    if type(easing) == 'string' then
        local fn = EASINGS[easing]
        if not fn then error(('%s: unknown easing %q'):format(what, easing), level) end
        return fn
    end
    if type(easing) ~= 'function' then
        error(('%s: expected a name, a function or nil'):format(what), level)
    end
    local previous = -math.huge
    for i = 0, 16 do
        local v = easing(i / 16)
        if type(v) ~= 'number' or v ~= v or v < previous - 1e-9 then
            error(('%s: the function must be monotonic (never decrease) on [0,1]'):format(what), level)
        end
        previous = v
    end
    if math.abs(easing(0)) > 1e-9 or math.abs(easing(1) - 1) > 1e-9 then
        error(('%s: the function must map 0 to 0 and 1 to 1'):format(what), level)
    end
    return function(t)
        local v = easing(t)
        return v < 0 and 0 or v > 1 and 1 or v
    end
end

-- Sequence position `delta` steps away, wrapping only for repeating modes.
local function neighbourPosition(self, delta)
    local n = #self._seq
    local p = self._position + delta
    if p >= 1 and p <= n then return p end
    if PAUSE_AT_END[self.playMode] or self._released then return nil end
    return (p - 1) % n + 1
end

-- How far into the current frame playback is, 0 to 1.
local function frameProgress(self)
    local pos = self._position
    local lo, hi = self._intervals[pos], self._intervals[pos + 1]
    local p = (displayTime(self) - lo) / (hi - lo)
    return p < 0 and 0 or p > 1 and 1 or p
end

-- Global multiplier applied to every animation's update (slow motion, pause menus).
local clock = { scale = 1 }

local function setTimeScale(scale)
    if type(scale) ~= 'number' or not (scale >= 0) or scale == math.huge then
        error(('time scale must be a finite number >= 0, got %s'):format(tostring(scale)), 2)
    end
    clock.scale = scale
end

local function getTimeScale()
    return clock.scale
end

return {
    clock               = clock,
    setTimeScale        = setTimeScale,
    getTimeScale        = getTimeScale,
    VALID_MODES         = VALID_MODES,
    PAUSE_AT_END        = PAUSE_AT_END,
    MODE_LIST           = MODE_LIST,
    EASINGS             = EASINGS,
    parseDurations      = parseDurations,
    buildIntervals      = buildIntervals,
    applyRegion         = applyRegion,
    applySequence       = applySequence,
    applyTiming         = applyTiming,
    initTiming          = initTiming,
    displayTime         = displayTime,
    locate              = locate,
    timerFor            = timerFor,
    timerForDisplay     = timerForDisplay,
    resolveEasing       = resolveEasing,
    neighbourPosition   = neighbourPosition,
    frameProgress       = frameProgress,
}
end

__modules['desAnim8.options'] = function(...)
-- Validation of the constructor `opts` table. Internal.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local isInteger = util.isInteger

local OPTION_NAMES = { 'ticks', 'weights', 'jitter', 'rng', 'randomLength', 'data' }
local KNOWN_OPTIONS  = {}
for _, name in ipairs(OPTION_NAMES) do KNOWN_OPTIONS[name] = true end

-- Returns a private copy of opts after validating it. `level` as in error().
local function checkOptions(opts, frameCount, level)
    if opts == nil then return {} end
    if type(opts) ~= 'table' then
        error(('opts must be a table, got %s'):format(type(opts)), level)
    end
    local o = {}
    for key, value in pairs(opts) do
        if not KNOWN_OPTIONS[key] then
            error(('unknown option %q'):format(tostring(key)), level)
        end
        o[key] = value
    end
    if o.ticks ~= nil and type(o.ticks) ~= 'boolean' then error('option ticks must be a boolean', level) end
    if o.rng ~= nil and type(o.rng) ~= 'function' then error('option rng must be a function returning [0,1)', level) end
    if o.jitter ~= nil and (type(o.jitter) ~= 'number' or not (o.jitter >= 0 and o.jitter < 1)) then
        error(('option jitter must be a number in [0,1), got %s'):format(tostring(o.jitter)), level)
    end
    if o.jitter and o.ticks then error('option jitter cannot be combined with ticks', level) end
    if o.randomLength ~= nil and (not isInteger(o.randomLength) or o.randomLength < 2) then
        error(('option randomLength must be an integer >= 2, got %s'):format(tostring(o.randomLength)), level)
    end
    if o.weights ~= nil then
        local w = o.weights
        if type(w) ~= 'table' then error('option weights must be a table', level) end
        local positive = 0
        for i = 1, frameCount do
            if type(w[i]) ~= 'number' or not (w[i] >= 0) or w[i] == math.huge then
                error(('option weights: entry %d must be a non-negative number, got %s'):format(i, tostring(w[i])), level)
            end
            if w[i] > 0 then positive = positive + 1 end
        end
        if frameCount > 1 and positive < 2 then
            error('option weights: at least two frames need a positive weight', level)
        end
        local copy = {}
        for i = 1, frameCount do copy[i] = w[i] end
        o.weights = copy
    end
    if o.data ~= nil then
        if type(o.data) ~= 'table' then
            error('option data must be a table of frame -> { name = value }', level)
        end
        local copy = {}
        for frame, values in pairs(o.data) do
            if not isInteger(frame) or frame < 1 or frame > frameCount then
                error(('option data: frame %s is outside [1,%d]'):format(tostring(frame), frameCount), level)
            end
            if type(values) ~= 'table' then
                error(('option data: frame %d must map to a table'):format(frame), level)
            end
            local c = {}
            for k, v in pairs(values) do c[k] = v end
            local rot = c.rotated
            if rot == true or rot == 'cw' then
                c.rotated = 'cw'
            elseif rot == false then
                c.rotated = nil
            elseif rot ~= nil and rot ~= 'ccw' then
                error(('option data: frame %d rotated must be true, "cw" or "ccw"'):format(frame), level)
            end
            local tf = c.transform
            if tf ~= nil then
                if type(tf) ~= 'table' then
                    error(('option data: frame %d transform must be a table'):format(frame), level)
                end
                local n = { x = 0, y = 0, r = 0, sx = 1, sy = 1 }
                for key in pairs(n) do
                    local v = tf[key]
                    if v ~= nil then
                        if type(v) ~= 'number' or v ~= v then
                            error(('option data: frame %d transform %s must be a number'):format(frame, key), level)
                        end
                        n[key] = v
                    end
                end
                c.transform = n
            end
            local t = c.trim
            if t ~= nil and (type(t) ~= 'table' or type(t.x) ~= 'number' or type(t.y) ~= 'number'
                    or type(t.w) ~= 'number' or type(t.h) ~= 'number' or not (t.w > 0 and t.h > 0)) then
                error(('option data: frame %d trim must be { x, y, w, h } with positive w and h'):format(frame), level)
            end
            copy[frame] = c
        end
        o.data = copy
    end
    return o
end

local function assertTickDurations(durations, level)
    for i = 1, #durations do
        if not isInteger(durations[i]) then
            error(('ticks mode needs integer durations, frame %d has %s'):format(i, tostring(durations[i])), level)
        end
    end
end

local function jittered(base, jitter, rng)
    local t = {}
    for i = 1, #base do t[i] = base[i] * (1 + (rng() * 2 - 1) * jitter) end
    return t
end

return {
    checkOptions        = checkOptions,
    assertTickDurations = assertTickDurations,
    jittered            = jittered,
}
end

__modules['desAnim8.events'] = function(...)
-- Hooks, frame callbacks and time markers. Internal helpers plus the Animation
-- methods that register callbacks.

local Animation = {}

-- Resolves a hook field that holds a function or the name of a method.
-- Level 3: hook <- callHook <- update <- the user's call.
local function callHook(self, name, ...)
    local cb = self[name]
    if cb == nil then return end
    if type(cb) == 'string' then
        local method = self[cb]
        if type(method) ~= 'function' then
            error(('%s: animation has no method %q'):format(name, cb), 3)
        end
        cb = method
    end
    if type(cb) ~= 'function' then
        error(('%s must be a function or a method name'):format(name), 3)
    end
    cb(self, ...)
end

-- Fires onFrame callbacks for every sequence position entered while moving from
-- oldPos to newPos. Callers pass loops already capped at 2: only the last cycle's
-- worth of entries is reported, so a huge dt cannot flood the callbacks.
local function fireFrames(self, oldPos, newPos, loops, reversed)
    local first, last = self._wrapFirst, self._wrapLast
    local len = last - first + 1
    local steps
    if not reversed then
        steps = loops == 0 and newPos - oldPos
            or (last - oldPos) + (loops - 1) * len + (newPos - first + 1)
    else
        steps = loops == 0 and oldPos - newPos
            or (oldPos - first) + (loops - 1) * len + (last - newPos + 1)
    end
    if steps <= 0 then return end
    local skip = steps > len and steps - len or 0
    local p, seq, cbs = oldPos, self._seq, self._onFrame
    for i = 1, steps do
        if reversed then
            p = p - 1
            if p < first then p = last end
        else
            p = p + 1
            if p > last then p = first end
        end
        if i > skip then
            local frame = seq[p]
            local list = cbs[frame]
            if list then
                for k = 1, #list do
                    local fn = list[k]
                    if fn then fn(self, frame) end
                end
            end
        end
    end
end

local function fireMarkers(self, oldT, newT, loops, reversed)
    local ms = self._markers
    local wstart, wend = self._wrapStart, self._wrapEnd
    for i = 1, #ms do
        local m = ms[i]
        local t = m.t
        local hit
        if not reversed then
            if loops == 0 then hit = t > oldT and t <= newT
            else hit = (t > oldT and t <= wend) or (t >= wstart and t <= newT) end
        else
            if loops == 0 then hit = t < oldT and t >= newT
            else hit = (t < oldT and t >= wstart) or (t <= wend and t >= newT) end
        end
        if hit then m.fn(self, t) end
    end
end

local function checkFrameNumber(self, n, what)
    if type(n) ~= 'number' or n ~= math.floor(n) or n < 1 or n > #self.frames then
        error(('%s: frame must be an integer in [1,%d], got %s'):format(what, #self.frames, tostring(n)), 3)
    end
end

-- Calls fn(anim, frame) every time frame `n` becomes the current frame.
function Animation:onFrame(n, fn)
    checkFrameNumber(self, n, 'onFrame')
    if type(fn) ~= 'function' then error('onFrame: expected a function', 2) end
    self._onFrame = self._onFrame or {}
    self._plain = nil
    local list = self._onFrame[n]
    if not list then list = {}; self._onFrame[n] = list end
    list[#list + 1] = fn
    return self
end

-- Removes one callback, or every callback of the frame when fn is omitted.
function Animation:offFrame(n, fn)
    checkFrameNumber(self, n, 'offFrame')
    local list = self._onFrame and self._onFrame[n]
    if not list then return self end
    if fn == nil then
        self._onFrame[n] = nil
    else
        for i = #list, 1, -1 do
            if list[i] == fn then table.remove(list, i); break end
        end
    end
    return self
end

-- Calls fn(anim, t) when playback crosses `t` seconds into the sequence. A
-- marker fires at most once per update.
function Animation:addMarker(t, fn)
    if type(t) ~= 'number' or not (t >= 0 and t <= self._totalDuration) then
        error(('addMarker: marker time must be in [0,%s], got %s'):format(
            tostring(self._totalDuration), tostring(t)), 2)
    end
    if type(fn) ~= 'function' then error('addMarker: expected a function', 2) end
    self._markers = self._markers or {}
    self._plain = nil
    self._markers[#self._markers + 1] = { t = t, fn = fn }
    return self
end

function Animation:clearMarkers()
    self._markers = nil
    self._plain = nil
    return self
end

return {
    methods     = Animation,
    callHook    = callHook,
    fireFrames  = fireFrames,
    fireMarkers = fireMarkers,
}
end

__modules['desAnim8.playback'] = function(...)
-- Advancing time and transport controls: update, pause/resume, reset, jumps and
-- the read-only queries. Methods are mixed into the Animation class.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local timing = require(PKG .. '.timing')
local events = require(PKG .. '.events')
local seekIndex = util.seekIndex
local PAUSE_AT_END, clock = timing.PAUSE_AT_END, timing.clock
local applyRegion, displayTime, locate, timerFor = timing.applyRegion, timing.displayTime, timing.locate, timing.timerFor
local callHook, fireFrames, fireMarkers = events.callHook, events.fireFrames, events.fireMarkers

local Animation = {}

-- True when update can take its shortcut: forward playback at speed 1 with no
-- hooks, markers, freeze, flash, easing, step, loop range or tick mode in play.
-- The answer is cached in _plain, and every method that changes one of those
-- things sets _plain = nil so it is worked out again.
local function isPlain(self)
    return not self._ticks and self._speed == 1 and self._freeze == 0 and self._started
        and not self._onFrame and not self._markers and not self._ease and not self._step
        and not self._flash and self._wrapStart == 0 and self._wrapEnd == self._totalDuration
end

function Animation:update(dt)
    if type(dt) ~= 'number' then
        error(('update: dt must be a number, got %s'):format(type(dt)), 2)
    end
    local plain = self._plain
    if plain == nil then
        plain = isPlain(self)
        self._plain = plain
    end
    if plain and self.status == 'playing' and dt > 0 and dt < math.huge then
        local timer = self._timer + dt * clock.scale
        if timer < self._totalDuration then
            self._timer = timer
            local position = seekIndex(self._intervals, timer)
            self._position, self.currentFrame = position, self._seq[position]
            return
        end
    end
    local ticks = self._ticks
    if ticks and dt ~= math.floor(dt) then
        error(('update: ticks mode needs an integer step, got %s'):format(tostring(dt)), 2)
    end
    local flash = self._flash
    if flash and dt > 0 then
        flash.left = flash.left - dt
        if flash.left <= 0 then
            self._flash = nil
            self._plain = nil
            self._styled = nil
        end
    end
    -- Also rejects NaN, which would otherwise poison the timer permanently.
    if self.status ~= 'playing' or not (dt > 0) or dt == math.huge then return end

    if self._freeze > 0 then
        self._plain = nil
        if dt <= self._freeze then
            self._freeze = self._freeze - dt
            return
        end
        dt = dt - self._freeze
        self._freeze = 0
    end
    -- speed and the time scale are validated finite, so step is never NaN or infinite.
    local step = dt * self._speed
    if not ticks then step = step * clock.scale end
    if step == 0 then return end

    if not self._started then
        self._started = true
        self._plain = nil
        callHook(self, 'onStart')
    end

    local onFrame, markers = self._onFrame, self._markers
    local oldTimer, oldPos = self._timer, self._position
    local timer = oldTimer + step
    local wstart, wend = self._wrapStart, self._wrapEnd
    local reversed, loops = step < 0, 0
    if not reversed then
        if timer >= wend then
            local span = wend - wstart
            loops = math.floor((timer - wstart) / span)
            timer = timer - span * loops
        end
    elseif timer < wstart then
        local span = wend - wstart
        loops = math.ceil((wstart - timer) / span)
        timer = timer + span * loops
    end

    local finished = false
    if loops ~= 0 then
        self._loops = self._loops + loops
        if PAUSE_AT_END[self.playMode] or self._released then
            finished = true
            if reversed then self:pauseAtStart() else self:pauseAtEnd() end
        end
    end
    if not finished then
        self._timer = timer
        if self._ease or self._step then
            self._position = seekIndex(self._intervals, displayTime(self))
        else
            -- timer < wend <= total here, so the end sentinel cannot apply.
            self._position = seekIndex(self._intervals, timer)
        end
        self.currentFrame = self._seq[self._position]
    end

    if onFrame or markers then
        local eventLoops = finished and 0 or loops
        if onFrame then
            fireFrames(self, oldPos, self._position, eventLoops > 2 and 2 or eventLoops, reversed)
        end
        if markers then
            fireMarkers(self, oldTimer, self._timer, eventLoops, reversed)
        end
    end
    if loops ~= 0 then
        callHook(self, 'onLoop', loops)
        if finished then callHook(self, 'onEnd') end
    end
end

-- Advances by whole ticks; for animations built with { ticks = true }.
function Animation:tick(n)
    self:update(n or 1)
end

-- Returns the current 1-based frame index and its Quad.
function Animation:getCurrentFrame()
    return self.currentFrame, self.frames[self.currentFrame]
end

function Animation:getCurrentFrameNumber()
    return self.currentFrame
end

function Animation:getDimensions()
    local _, _, w, h = self.frames[self.currentFrame]:getViewport()
    if self._rotated and self._rotated[self.currentFrame] then return h, w end
    return w, h
end

function Animation:getFrameCount()
    return #self.frames
end

-- Length in seconds of one full play-through. For 'bounce' modes that includes
-- the return trip.
function Animation:getDuration()
    return self._totalDuration
end

function Animation:getPlayMode()
    return self.playMode
end

-- Seconds left until the end of the sequence.
function Animation:getRemainingTime()
    if self._speed < 0 then return self._timer end
    return self._totalDuration - self._timer
end

-- Position inside one play-through, 0 (start) to 1 (end).
function Animation:getPhase()
    return self._timer / self._totalDuration
end

-- Jumps to a position inside one play-through; values outside 0..1 are clamped.
function Animation:setPhase(p)
    if type(p) ~= 'number' or p ~= p then
        error(('setPhase: phase must be a number, got %s'):format(tostring(p)), 2)
    end
    p = math.max(0, math.min(1, p))
    self._timer = p * self._totalDuration
    locate(self)
end

-- Completed play-throughs since construction or reset().
function Animation:getLoopCount()
    return self._loops
end

-- True once a 'once'/'bounceOnce' (or released loop-range) animation has reached
-- its end, which is the start when it plays backwards.
function Animation:isFinished()
    if not (PAUSE_AT_END[self.playMode] or self._released) then return false end
    if self._speed >= 0 then return self._timer >= self._totalDuration end
    return self._timer <= 0 and self.status == 'paused'
end

function Animation:pause()
    self.status = 'paused'
end

-- Does nothing once a 'once'/'bounceOnce' animation has finished (it would only
-- re-fire onLoop); use reset() or gotoFrame() to play it again. A looping
-- animation parked at its end starts over instead.
function Animation:resume()
    local finishMode = PAUSE_AT_END[self.playMode] or self._released
    if self._speed >= 0 then
        if self._timer >= self._totalDuration then
            if finishMode then return end
            self._timer = 0
            locate(self)
        end
    elseif self._timer <= 0 then
        if finishMode then return end
        self._timer = self._totalDuration
        locate(self)
    end
    self.status = 'playing'
end

-- "End" is the last entry of the play sequence: the last frame for loop and
-- once, frame 2 for bounce (the frame before the cycle repeats) and frame 1
-- for bounceOnce.
function Animation:pauseAtEnd()
    self._position    = #self._seq
    self._timer       = self._totalDuration
    self.currentFrame = self._seq[self._position]
    self.status       = 'paused'
end

function Animation:pauseAtStart()
    self._position    = 1
    self._timer       = 0
    self._started     = false
    self._plain       = nil
    self.currentFrame = self._seq[1]
    self.status       = 'paused'
end

-- Alias for pauseAtStart (backward compat).
function Animation:stop()
    self:pauseAtStart()
end

function Animation:reset()
    self._position    = 1
    self._timer       = 0
    self._loops       = 0
    self._freeze      = 0
    self._started     = false
    self._plain       = nil
    self._released    = false
    applyRegion(self)
    self.currentFrame = self._seq[1]
    self.status       = 'playing'
end

function Animation:gotoFrame(n)
    if type(n) ~= 'number' or n ~= math.floor(n) then
        error(('gotoFrame: frame must be an integer, got %s'):format(tostring(n)), 2)
    end
    if n < 1 or n > #self.frames then
        error(('gotoFrame: %d out of range [1,%d]'):format(n, #self.frames), 2)
    end
    for i, fi in ipairs(self._seq) do
        if fi == n then
            self._position    = i
            self._timer       = timerFor(self, i)
            self.currentFrame = n
            -- with setStep a frame shorter than the step cannot be shown: keep
            -- the displayed frame consistent with the timer
            if self._step or self._ease then locate(self) end
            return
        end
    end
end

function Animation:isPlaying()
    return self.status == 'playing'
end

function Animation:isPaused()
    return self.status == 'paused'
end

return { methods = Animation }
end

__modules['desAnim8.timeline'] = function(...)
-- Playback shaping: speed, hit-stop, stepped time, easing, loop ranges, waiting
-- and runtime changes of play mode and durations. Mixed into Animation.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local timing = require(PKG .. '.timing')
local options = require(PKG .. '.options')
local isInteger = util.isInteger
local VALID_MODES, MODE_LIST = timing.VALID_MODES, timing.MODE_LIST
local parseDurations, applyTiming, applySequence = timing.parseDurations, timing.applyTiming, timing.applySequence
local applyRegion, locate, resolveEasing = timing.applyRegion, timing.locate, timing.resolveEasing
local displayTime, timerFor, timerForDisplay = timing.displayTime, timing.timerFor, timing.timerForDisplay
local assertTickDurations = options.assertTickDurations

local Animation = {}

local function assertSpeedValue(self, v, what)
    if type(v) ~= 'number' or v ~= v or v == math.huge or v == -math.huge then
        error(('%s must be a finite number, got %s'):format(what, tostring(v)), 3)
    end
    if self._ticks and v ~= math.floor(v) then
        error(('%s must be an integer in ticks mode, got %s'):format(what, tostring(v)), 3)
    end
end

-- Playback rate: 1 is normal, 2 doubles it, negative plays backwards, 0 holds.
function Animation:setSpeed(rate)
    assertSpeedValue(self, rate, 'setSpeed: speed')
    self._speed = rate
    self._plain = nil
    return self
end

function Animation:getSpeed()
    return self._speed
end

-- Sets the speed so one play-through lasts `seconds`; the direction is kept.
function Animation:fitDuration(seconds)
    if self._ticks then error('fitDuration: not available in ticks mode', 2) end
    if type(seconds) ~= 'number' or not (seconds > 0) or seconds == math.huge then
        error(('fitDuration: seconds must be a positive number, got %s'):format(tostring(seconds)), 2)
    end
    self._speed = (self._speed < 0 and -1 or 1) * self._totalDuration / seconds
    self._plain = nil
    return self
end

-- Ignores updates for `seconds` of dt (hit-stop). Leftover dt in the same call
-- advances normally.
function Animation:freeze(seconds)
    if type(seconds) ~= 'number' or not (seconds >= 0) or seconds == math.huge then
        error(('freeze: seconds must be a non-negative number, got %s'):format(tostring(seconds)), 2)
    end
    if self._ticks and seconds ~= math.floor(seconds) then
        error('freeze: seconds must be an integer in ticks mode', 2)
    end
    self._freeze = seconds
    self._plain = nil
    return self
end

-- Quantizes the displayed time to multiples of `seconds` (animating "on twos").
-- nil turns it off.
function Animation:setStep(seconds)
    if seconds ~= nil and (type(seconds) ~= 'number' or not (seconds > 0) or seconds == math.huge) then
        error(('setStep: step must be a positive number or nil, got %s'):format(tostring(seconds)), 2)
    end
    self._step = seconds
    self._plain = nil
    locate(self)
    return self
end

-- Remaps time across the sequence. `easing` is a name from EASINGS, a function
-- from [0,1] to [0,1] that never decreases, or nil for linear.
function Animation:setEasing(easing)
    self._ease = resolveEasing(easing, 'setEasing', 3)
    self._plain = nil
    locate(self)
    return self
end

-- Jumps to a random point of the play-through, to keep crowds out of sync.
function Animation:randomizeStart(rng)
    local v = (rng or math.random)()
    if type(v) ~= 'number' or not (v >= 0 and v <= 1) then
        error('randomizeStart: rng must return a number in [0,1]', 2)
    end
    self:setPhase(v)
end

-- Switches the play mode, keeping the current frame where the new sequence has it.
function Animation:setPlayMode(mode)
    if not VALID_MODES[mode] then
        error(('setPlayMode: unknown play mode %s; expected %s'):format(
            type(mode) == 'string' and ('%q'):format(mode) or tostring(mode), MODE_LIST), 2)
    end
    local frame, oldPos = self.currentFrame, self._position
    self.playMode = mode
    self._loopFrom, self._loopTo, self._released = nil, nil, false
    applyTiming(self)
    local seq = self._seq
    local n, found = #seq, 1
    for k = 0, n - 1 do
        local i = (oldPos - 1 + k) % n + 1
        if seq[i] == frame then found = i; break end
    end
    self._position    = found
    self._timer       = timerFor(self, found)
    self.currentFrame = seq[found]
    if self._step or self._ease then locate(self) end
    return self
end

-- Replaces the durations (same formats as the constructor) keeping the position
-- and how far into the current frame playback is.
function Animation:setDurations(durations)
    local fresh = parseDurations(durations, #self.frames, 3)
    if self._ticks then assertTickDurations(fresh, 3) end
    local pos = self._position
    local lo, hi = self._intervals[pos], self._intervals[pos + 1]
    -- progress is measured on the displayed time, which differs from the timer
    -- while an easing or a step is active
    local progress = (displayTime(self) - lo) / (hi - lo)
    progress = progress < 0 and 0 or progress > 1 and 1 or progress
    self._baseDurations, self._durations = fresh, fresh
    applySequence(self, self._seq)
    local lo2, hi2 = self._intervals[pos], self._intervals[pos + 1]
    self._timer = math.min(timerForDisplay(self, lo2 + progress * (hi2 - lo2)), self._totalDuration)
    locate(self)
    return self
end

-- Loop frames from..to (loop mode only): playback runs 1..to once, then keeps
-- wrapping back to `from`. release() lets it run on to the end and finish.
function Animation:setLoopRange(from, to)
    if self.playMode ~= 'loop' then error('setLoopRange: only available in loop mode', 2) end
    local n = #self.frames
    if not isInteger(from) or not isInteger(to) or from < 1 or to > n or from > to then
        error(('setLoopRange: range %s-%s invalid for %d frames'):format(tostring(from), tostring(to), n), 2)
    end
    self._loopFrom, self._loopTo, self._released = from, to, false
    applyRegion(self)
    return self
end

function Animation:clearLoopRange()
    self._loopFrom, self._loopTo, self._released = nil, nil, false
    applyRegion(self)
    return self
end

function Animation:release()
    if not self._loopFrom then error('release: no loop range set (see setLoopRange)', 2) end
    self._released = true
    applyRegion(self)
    return self
end

-- Inside a coroutine: yields until the animation finishes (once modes) or
-- completes its next loop. Polls once per resume, so it works with any scheduler
-- that resumes the coroutine every frame.
function Animation:wait()
    local co, isMain = coroutine.running()
    if co == nil or isMain then error('wait: must be called inside a coroutine', 2) end
    local start = self._loops
    while not (self:isFinished() or self._loops > start) do coroutine.yield() end
end

return { methods = Animation }
end

__modules['desAnim8.frameinfo'] = function(...)
-- What gets drawn for the current frame: transform parameters with flip, trim,
-- pivot and keyframe transforms applied, per-frame data and SpriteBatch helpers.
local PKG = (...):match('^(.*)%.[^.]*$')
local timing = require(PKG .. '.timing')
local neighbourPosition, frameProgress = timing.neighbourPosition, timing.frameProgress
local EASINGS, resolveEasing = timing.EASINGS, timing.resolveEasing

local Animation = {}

local IDENTITY_TRANSFORM = { x = 0, y = 0, r = 0, sx = 1, sy = 1 }
local HALF_PI = math.pi / 2

function Animation:getFrameProgress()
    return frameProgress(self)
end

-- Keyframe offsets of the current frame, blended towards the next frame's when
-- interpolation is on. Returns x, y, r, sx, sy.
local function frameTransform(self, f)
    local c = self._transforms[f] or IDENTITY_TRANSFORM
    if not self._interp then return c.x, c.y, c.r, c.sx, c.sy end
    local p = neighbourPosition(self, 1)
    local n = p and (self._transforms[self._seq[p]] or IDENTITY_TRANSFORM) or c
    local t = self._interpEase(frameProgress(self))
    return c.x + (n.x - c.x) * t, c.y + (n.y - c.y) * t, c.r + (n.r - c.r) * t,
        c.sx + (n.sx - c.sx) * t, c.sy + (n.sy - c.sy) * t
end

-- Blends keyframe `transform` data (see the data option) between frames instead
-- of stepping. `easing` shapes the blend; default linear.
function Animation:setInterpolation(enabled, easing)
    if type(enabled) ~= 'boolean' then error('setInterpolation: expected a boolean', 2) end
    self._interp = enabled or nil
    self._interpEase = resolveEasing(easing, 'setInterpolation', 3) or EASINGS.linear
    return self
end

-- Returns the quad and all love.graphics.draw transform parameters, with flip
-- and trim adjustments applied. Use this when you need to draw with extra
-- transforms, or to add the animation to a SpriteBatch.
--
-- A flip mirrors the sprite inside its (untrimmed) source frame of size W x H,
-- so the drawn position stays put. With a trim offset (tx, ty) the quad is only
-- part of that frame: the origin becomes ox - tx, or W - tx - ox once mirrored.
function Animation:getFrameInfo(x, y, r, sx, sy, ox, oy, kx, ky)
    local fh, fv = self.flippedH, self.flippedV
    -- _fancy: some feature beyond a plain frame is configured (trim, transforms,
    -- pixel snap, auto pivot). Cached; the setters reset it to nil.
    local fancy = self._fancy
    if fancy == nil then
        fancy = (self._trim or self._transforms or self._rotated or self._snap or self._autoPivot) and true or false
        self._fancy = fancy
    end
    if not fancy then
        local frame = self.frames[self.currentFrame]
        if not (fh or fv) then return frame, x, y, r, sx, sy, ox, oy, kx, ky end
        -- flips only: the original, short formula
        r,  sx = r or 0, sx or 1
        sy     = sy or sx
        ox, oy = ox or 0, oy or 0
        kx, ky = kx or 0, ky or 0
        local _, _, w, h = frame:getViewport()
        if fh then
            sx = -sx
            ox = w - ox
            kx = -kx
            ky = -ky
        end
        if fv then
            sy = -sy
            oy = h - oy
            kx = -kx
            ky = -ky
        end
        return frame, x, y, r, sx, sy, ox, oy, kx, ky
    end
    local f = self.currentFrame
    local frame = self.frames[f]
    local trim = self._trim and self._trim[f]
    if self._snap then
        if x then x = math.floor(x + 0.5) end
        if y then y = math.floor(y + 0.5) end
    end
    if self._autoPivot then
        local d = self._data and self._data[f]
        local pivot = d and d.pivot
        if pivot then
            if ox == nil then ox = pivot.x end
            if oy == nil then oy = pivot.y end
        end
    end
    local dx, dy, dr, tsx, tsy
    if self._transforms then dx, dy, dr, tsx, tsy = frameTransform(self, f) end
    local rotated = self._rotated and self._rotated[f]
    if fh or fv or trim or dx or rotated then
        r,  sx = r or 0, sx or 1
        sy     = sy or sx -- love.graphics.draw defaults sy to sx
        ox, oy = ox or 0, oy or 0
        kx, ky = kx or 0, ky or 0
        if dx then
            -- Offsets are in sprite pixels: a mirrored sprite mirrors them, and a
            -- single mirror reverses the sense of rotation.
            if fh then dx = -dx end
            if fv then dy = -dy end
            if fh ~= fv then dr = -dr end
            ox, oy = ox - dx, oy - dy
            r = r + dr
            sy, sx = sy * tsy, sx * tsx
        end
        local tx, ty, w, h
        if trim then
            tx, ty, w, h = trim.x, trim.y, trim.w, trim.h
        else
            tx, ty = 0, 0
            local _
            _, _, w, h = frame:getViewport()
            if rotated then w, h = h, w end
        end
        if fh then
            sx = -sx
            ox = w - tx - ox
            kx = -kx
            ky = -ky
        else
            ox = ox - tx
        end
        if fv then
            sy = -sy
            oy = h - ty - oy
            kx = -kx
            ky = -ky
        else
            oy = oy - ty
        end
        if rotated then
            -- Everything above treated the frame as upright. The stored quad is that
            -- sprite turned 90 degrees, so turn the parameters the other way: swap
            -- the scale axes, swap and negate the shear, rotate by -90 (clockwise
            -- storage) or +90 degrees, and move the origin into the quad's axes.
            local _, _, qw, qh = frame:getViewport()
            sx, sy = sy, sx
            kx, ky = -ky, -kx
            if rotated == 'cw' then
                r = r - HALF_PI
                ox, oy = qw - oy, ox
            else
                r = r + HALF_PI
                ox, oy = oy, qh - ox
            end
        end
    end
    return frame, x, y, r, sx, sy, ox, oy, kx, ky
end

-- Value stored under `name` for a frame (default: the current one) through the
-- `data` constructor option, or nil. Shared with clones; treat it as read only.
function Animation:getFrameData(name, frame)
    local d = self._data and self._data[frame or self.currentFrame]
    return d and d[name]
end

-- When on, ox and oy default to the frame's `pivot` data ({ x, y } in source
-- frame pixels) wherever the caller leaves them out.
function Animation:setAutoPivot(enabled)
    if type(enabled) ~= 'boolean' then error('setAutoPivot: expected a boolean', 2) end
    self._autoPivot = enabled
    self._fancy = nil
    return self
end

-- World-space rectangle of a { x, y, w, h } stored under `name` (for example a
-- hitbox), given the same x, y, sx, sy, ox, oy you draw with. Honours the
-- current flips; rotation is not supported. Returns x, y, w, h or nil.
function Animation:getWorldRect(name, x, y, sx, sy, ox, oy)
    local f = self.currentFrame
    local rect = self:getFrameData(name, f)
    if rect == nil then return nil end
    sx = sx or 1
    sy = sy or sx
    if self._autoPivot then
        local pivot = self:getFrameData('pivot', f)
        if pivot then
            if ox == nil then ox = pivot.x end
            if oy == nil then oy = pivot.y end
        end
    end
    ox, oy = ox or 0, oy or 0
    local trim = self._trim and self._trim[f]
    local w, h
    if trim then
        w, h = trim.w, trim.h
    else
        local _
        _, _, w, h = self.frames[f]:getViewport()
        if self._rotated and self._rotated[f] then w, h = h, w end
    end
    local rx, ry = rect.x, rect.y
    if self.flippedH then rx = w - rx - rect.w end
    if self.flippedV then ry = h - ry - rect.h end
    local x0, y0 = x + sx * (rx - ox), y + sy * (ry - oy)
    local x1, y1 = x0 + sx * rect.w, y0 + sy * rect.h
    return math.min(x0, x1), math.min(y0, y1), math.abs(x1 - x0), math.abs(y1 - y0)
end

-- Adds the current frame (flip applied) to a SpriteBatch and returns its id.
function Animation:addToBatch(batch, ...)
    return batch:add(self:getFrameInfo(...))
end

-- Rewrites sprite `id` of a SpriteBatch with the current frame.
function Animation:setInBatch(batch, id, ...)
    return batch:set(id, self:getFrameInfo(...))
end

return { methods = Animation }
end

__modules['desAnim8.debug'] = function(...)
-- Debug drawing helpers and the onion-skin colors. Public as desAnim8.debug.

local dbg = {
    onionBefore = { 1, 0.3, 0.3, 0.35 },
    onionAfter  = { 0.3, 1, 0.3, 0.35 },
}

-- Segment bar of the whole sequence with a playhead, for debugging timing.
function dbg.drawTimeline(anim, x, y, w, h)
    local gfx = love.graphics
    local pr, pg, pb, pa = gfx.getColor()
    local total, intervals = anim._totalDuration, anim._intervals
    for i = 1, #anim._seq do
        local x0 = x + w * intervals[i] / total
        local x1 = x + w * intervals[i + 1] / total
        local shade = i == anim._position and 0.9 or (i % 2 == 0 and 0.35 or 0.5)
        gfx.setColor(shade, shade, shade, 0.8)
        gfx.rectangle('fill', x0, y, x1 - x0, h)
    end
    gfx.setColor(1, 1, 1, 1)
    gfx.rectangle('line', x, y, w, h)
    local px = x + w * anim._timer / total
    gfx.setColor(1, 0.2, 0.2, 1)
    gfx.line(px, y, px, y + h)
    gfx.setColor(pr, pg, pb, pa)
end

-- If the point (mx, my) is inside the timeline rectangle, pauses the animation
-- on the matching phase and returns true.
function dbg.scrub(anim, mx, my, x, y, w, h)
    if mx < x or mx > x + w or my < y or my > y + h then return false end
    anim:setPhase((mx - x) / w)
    anim:pause()
    return true
end

return dbg
end

__modules['desAnim8.render'] = function(...)
-- Drawing and its style: tint, blend, shader, flash, flips, facing, pixel snap,
-- trail, onion skin and bounds. Methods are mixed into the Animation class.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local timing = require(PKG .. '.timing')
local dbg = require(PKG .. '.debug')
local isInteger, flipFor = util.isInteger, util.flipFor
local neighbourPosition = timing.neighbourPosition

local Animation = {}

-- Frame info for another frame index of the same animation.
local function frameInfoFor(self, frameIndex, ...)
    local saved = self.currentFrame
    self.currentFrame = frameIndex
    local info = { self:getFrameInfo(...) }
    self.currentFrame = saved
    return info
end

-- Draws with whatever render state is configured (tint, blend, shader, trail,
-- onion skin) and puts the previous graphics state back afterwards. Without any
-- of that it is a single love.graphics.draw call.
local function drawFrame(self, image, ...)
    local gfx = love.graphics
    -- _styled: any tint, flash, blend, shader, trail or onion is set. Cached; the
    -- setters (and the flash running out) reset it to nil.
    local styled = self._styled
    if styled == nil then
        styled = (self._color or self._flash or self._blend or self._shader or self._trail or self._onion)
            and true or false
        self._styled = styled
    end
    if not styled then
        gfx.draw(image, self:getFrameInfo(...))
        return
    end
    local trail, onion = self._trail, self._onion
    local tint, flash, blend, shader = self._color, self._flash, self._blend, self._shader

    local pr, pg, pb, pa = gfx.getColor()
    local cr, cg, cb, ca = pr, pg, pb, pa
    if flash then
        cr, cg, cb, ca = flash.r, flash.g, flash.b, tint and tint[4] or pa
    elseif tint then
        cr, cg, cb, ca = tint[1], tint[2], tint[3], tint[4]
    end
    local recolor = tint or flash or trail or onion
    local pbm, pbam, psh
    if blend then
        pbm, pbam = gfx.getBlendMode()
        gfx.setBlendMode(blend[1], blend[2])
    end
    if shader then
        psh = gfx.getShader()
        local uniforms = self._uniforms
        if uniforms then
            for name, value in pairs(uniforms) do shader:send(name, value) end
        end
        gfx.setShader(shader)
    end

    if trail then
        local entries = trail.entries
        local n = #entries
        for i = 1, n do
            local e = entries[i]
            gfx.setColor(cr, cg, cb, ca * trail.alpha * i / (n + 1))
            gfx.draw(image, e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10])
        end
    end
    if onion then
        local before, after = dbg.onionBefore, dbg.onionAfter
        for k = onion[1], 1, -1 do
            local p = neighbourPosition(self, -k)
            if p then
                local e = frameInfoFor(self, self._seq[p], ...)
                gfx.setColor(before[1], before[2], before[3], before[4] * ca)
                gfx.draw(image, e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10])
            end
        end
        for k = 1, onion[2] do
            local p = neighbourPosition(self, k)
            if p then
                local e = frameInfoFor(self, self._seq[p], ...)
                gfx.setColor(after[1], after[2], after[3], after[4] * ca)
                gfx.draw(image, e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10])
            end
        end
    end

    if recolor then gfx.setColor(cr, cg, cb, ca) end
    if trail then
        local info = { self:getFrameInfo(...) }
        gfx.draw(image, info[1], info[2], info[3], info[4], info[5], info[6], info[7], info[8], info[9], info[10])
        trail.draws = trail.draws + 1
        if (trail.draws - 1) % trail.spacing == 0 then
            local entries = trail.entries
            entries[#entries + 1] = info
            if #entries > trail.count then table.remove(entries, 1) end
        end
    else
        gfx.draw(image, self:getFrameInfo(...))
    end

    if shader then gfx.setShader(psh) end
    if blend then gfx.setBlendMode(pbm, pbam) end
    if recolor then gfx.setColor(pr, pg, pb, pa) end
end

-- With a bound image:    anim:draw(x, y [, r, sx, sy, ox, oy, kx, ky])
-- Without one (image=nil): anim:draw(image, x, y [, ...]) -- the leading
-- argument is the image to draw onto.
function Animation:draw(a, b, ...)
    if self.image ~= nil then
        if type(a) ~= 'number' then
            error('draw: this animation has an image bound; call anim:draw(x, y [, ...]) without the image', 2)
        end
        drawFrame(self, self.image, a, b, ...)
    else
        if a == nil or type(a) == 'number' then
            error('draw: no image bound; call anim:draw(image, x, y [, ...])', 2)
        end
        drawFrame(self, a, b, ...)
    end
end

-- Tint multiplied into the sprite; call with no arguments to go back to the
-- current graphics color. Values are 0..1.
function Animation:setColor(r, g, b, a)
    if r == nil then
        self._color = nil
        self._styled = nil
        return self
    end
    a = a == nil and 1 or a
    if type(r) ~= 'number' or type(g) ~= 'number' or type(b) ~= 'number' or type(a) ~= 'number' then
        error('setColor: expected numeric r, g, b [, a] (0..1) or no arguments', 2)
    end
    self._color = { r, g, b, a }
    self._styled = nil
    return self
end

function Animation:setAlpha(a)
    if type(a) ~= 'number' then error('setAlpha: alpha must be a number (0..1)', 2) end
    local c = self._color
    if c then c[4] = a else self._color = { 1, 1, 1, a } end
    self._styled = nil
    return self
end

function Animation:setBlendMode(mode, alphaMode)
    if mode ~= nil and type(mode) ~= 'string' then error('setBlendMode: blend mode must be a string or nil', 2) end
    self._blend = mode and { mode, alphaMode } or nil
    self._styled = nil
    return self
end

-- Draws with `shader`, sending the name -> value pairs in `uniforms` first.
function Animation:setShader(shader, uniforms)
    if uniforms ~= nil and type(uniforms) ~= 'table' then error('setShader: uniforms must be a table', 2) end
    self._shader   = shader
    self._styled   = nil
    self._uniforms = shader and uniforms or nil
    return self
end

-- Overrides the tint for `seconds` of update time (hit flash). The tint is
-- multiplicative, so a white flash needs desAnim8.shaders.whiteFlash.
function Animation:flash(seconds, r, g, b)
    if type(seconds) ~= 'number' or not (seconds > 0) or seconds == math.huge then
        error(('flash: seconds must be a positive number, got %s'):format(tostring(seconds)), 2)
    end
    self._flash = { left = seconds, r = r or 1, g = g or 1, b = b or 1 }
    self._styled = nil
    self._plain = nil
    return self
end

-- Flips horizontally so the sprite faces the sign of dx (0 keeps the current
-- side). Sheets are assumed to face right; see setDefaultFacing.
function Animation:faceTowards(dx)
    if type(dx) ~= 'number' or dx ~= dx then
        error(('faceTowards: dx must be a number, got %s'):format(tostring(dx)), 2)
    end
    if dx ~= 0 then self.flippedH = flipFor(dx, self._facing or 1) end
    return self
end

function Animation:setDefaultFacing(direction)
    if direction ~= 1 and direction ~= -1 then
        error('setDefaultFacing: facing must be 1 (sheet faces right) or -1 (faces left)', 2)
    end
    self._facing = direction
    return self
end

-- Rounds the draw position to whole pixels.
function Animation:setPixelSnap(enabled)
    if type(enabled) ~= 'boolean' then error('setPixelSnap: expected a boolean', 2) end
    self._snap = enabled or nil
    self._fancy = nil
    return self
end

-- Keeps `count` ghosts of earlier draws (one every `spacing` draws) and draws
-- them behind the sprite with alpha rising towards the newest. `alpha` is the
-- strongest ghost's share (default 0.5). nil clears the trail.
function Animation:setTrail(count, spacing, alpha)
    if count == nil or count == 0 then
        self._trail = nil
        self._styled = nil
        return self
    end
    spacing, alpha = spacing or 1, alpha or 0.5
    if not isInteger(count) or count < 1 or not isInteger(spacing) or spacing < 1
            or type(alpha) ~= 'number' or not (alpha > 0 and alpha <= 1) then
        error('setTrail: expected an integer count >= 1, an integer spacing >= 1 and an alpha in (0,1]', 2)
    end
    self._trail = { count = count, spacing = spacing, alpha = alpha, entries = {}, draws = 0 }
    self._styled = nil
    return self
end

-- Recorded ghosts, oldest first. Each entry is { quad, x, y, r, sx, sy, ox, oy, kx, ky },
-- ready for love.graphics.draw or a SpriteBatch.
function Animation:getTrail()
    return self._trail and self._trail.entries or {}
end

-- Draws `before` earlier and `after` later frames of the sequence, tinted, behind
-- the sprite (animation debugging). Pass 0, 0 or nil to turn it off.
function Animation:setOnion(before, after)
    before, after = before or 0, after or 0
    if not isInteger(before) or not isInteger(after) or before < 0 or after < 0 then
        error('setOnion: before and after must be non-negative integers', 2)
    end
    self._onion = (before > 0 or after > 0) and { before, after } or nil
    self._styled = nil
    return self
end

-- Outlines the current frame's rectangle with the transform draw would use.
function Animation:drawBounds(x, y, r, sx, sy, ox, oy, kx, ky)
    local gfx = love.graphics
    local quad, fx, fy, fr, fsx, fsy, fox, foy, fkx, fky = self:getFrameInfo(x, y, r, sx, sy, ox, oy, kx, ky)
    local _, _, w, h = quad:getViewport()
    gfx.push()
    gfx.translate(fx, fy)
    gfx.rotate(fr or 0)
    gfx.scale(fsx or 1, fsy or fsx or 1)
    if fkx or fky then gfx.shear(fkx or 0, fky or 0) end
    gfx.translate(-(fox or 0), -(foy or 0))
    gfx.rectangle('line', 0, 0, w, h)
    gfx.pop()
end

-- Toggle horizontal flip. Returns self so calls can be chained.
function Animation:flipH()
    self.flippedH = not self.flippedH
    return self
end

-- Toggle vertical flip. Returns self so calls can be chained.
function Animation:flipV()
    self.flippedV = not self.flippedV
    return self
end

-- Absolute flip setters; safe to call every frame, unlike the toggles.
function Animation:setFlipH(flipped)
    if type(flipped) ~= 'boolean' then error('setFlipH: expected a boolean', 2) end
    self.flippedH = flipped
    return self
end

function Animation:setFlipV(flipped)
    if type(flipped) ~= 'boolean' then error('setFlipV: expected a boolean', 2) end
    self.flippedV = flipped
    return self
end

return { methods = Animation }
end

__modules['desAnim8.state'] = function(...)
-- Savable playback state. Mixed into Animation.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local timing = require(PKG .. '.timing')
local isInteger = util.isInteger
local applyRegion, applySequence, locate = timing.applyRegion, timing.applySequence, timing.locate

local Animation = {}

local STATE_VERSION = 1

-- Plain-table snapshot of the playback state, for save games, replays and
-- rollback. Restore it with setState on an animation built the same way.
function Animation:getState()
    local state = {
        v        = STATE_VERSION,
        playMode = self.playMode,
        timer    = self._timer,
        status   = self.status,
        flippedH = self.flippedH,
        flippedV = self.flippedV,
        loops    = self._loops,
        speed    = self._speed,
        freeze   = self._freeze,
        started  = self._started,
        released = self._released,
    }
    if self.playMode == 'random' then
        state.seq = {}
        for i = 1, #self._seq do state.seq[i] = self._seq[i] end
    end
    return state
end

function Animation:setState(s)
    if type(s) ~= 'table' then error('setState: state must be a table from getState()', 2) end
    if s.v ~= STATE_VERSION then
        error(('setState: unsupported state version %s'):format(tostring(s.v)), 2)
    end
    if s.playMode ~= self.playMode then
        error(('setState: play mode mismatch (state %s, animation %s)'):format(
            tostring(s.playMode), tostring(self.playMode)), 2)
    end
    local seq
    if self.playMode == 'random' then
        if type(s.seq) ~= 'table' or #s.seq == 0 then error('setState: random mode state needs a seq list', 2) end
        seq = {}
        for i = 1, #s.seq do
            local f = s.seq[i]
            if not isInteger(f) or f < 1 or f > #self.frames then
                error(('setState: seq entry %d is not a frame index'):format(i), 2)
            end
            seq[i] = f
        end
    end
    local seqDur
    if seq then
        seqDur = 0
        for i = 1, #seq do seqDur = seqDur + self._durations[seq[i]] end
    end
    local total = seqDur or self._totalDuration
    if type(s.timer) ~= 'number' or not (s.timer >= 0 and s.timer <= total) then
        error(('setState: timer %s outside [0,%s]'):format(tostring(s.timer), tostring(total)), 2)
    end
    if s.status ~= 'playing' and s.status ~= 'paused' then
        error(('setState: invalid status %s'):format(tostring(s.status)), 2)
    end
    if type(s.flippedH) ~= 'boolean' then error('setState: flippedH must be a boolean', 2) end
    if type(s.flippedV) ~= 'boolean' then error('setState: flippedV must be a boolean', 2) end
    if type(s.loops) ~= 'number' or s.loops < 0 or s.loops ~= math.floor(s.loops) then
        error(('setState: loops must be a non-negative integer, got %s'):format(tostring(s.loops)), 2)
    end
    local speed = s.speed == nil and 1 or s.speed
    if type(speed) ~= 'number' or speed ~= speed or speed == math.huge or speed == -math.huge then
        error(('setState: invalid speed %s'):format(tostring(s.speed)), 2)
    end
    local freeze = s.freeze == nil and 0 or s.freeze
    if type(freeze) ~= 'number' or not (freeze >= 0) or freeze == math.huge then
        error(('setState: invalid freeze %s'):format(tostring(s.freeze)), 2)
    end
    local started, released = s.started == true, s.released == true
    if released and not self._loopFrom then
        error('setState: state was released but this animation has no loop range', 2)
    end

    if seq then applySequence(self, seq) end
    self._released = released
    applyRegion(self)
    self._timer    = s.timer
    self.status    = s.status
    self.flippedH  = s.flippedH
    self.flippedV  = s.flippedV
    self._loops    = s.loops
    self._speed    = speed
    self._freeze   = freeze
    self._started  = started
    self._plain    = nil
    locate(self)
    return self
end

return { methods = Animation }
end

__modules['desAnim8.animation'] = function(...)
-- The Animation class: construction and cloning. Behavior lives in the mixin
-- modules (playback, timeline, events, frameinfo, render, state), merged below.
local PKG = (...):match('^(.*)%.[^.]*$')
local timing = require(PKG .. '.timing')
local options = require(PKG .. '.options')
local VALID_MODES, MODE_LIST = timing.VALID_MODES, timing.MODE_LIST
local parseDurations, initTiming = timing.parseDurations, timing.initTiming
local applyTiming, applyRegion = timing.applyTiming, timing.applyRegion
local checkOptions, assertTickDurations, jittered = options.checkOptions, options.assertTickDurations, options.jittered

-- Instances get their own class table so they do not inherit the module's
-- constructors and metadata.
local Animation = {}
Animation.__index = Animation

-- Called from desAnim8.new / newAnimation, so the user's call is 3 frames up.
local function build(image, frames, durations, playMode, opts)
    if type(frames) ~= 'table' then
        error('frames must be a list of quads, e.g. from grid(\'1-4\', 1)', 3)
    end
    if #frames == 0 then error('desAnim8.new: frames list is empty', 3) end
    playMode = playMode or 'loop'
    if not VALID_MODES[playMode] then
        error(('desAnim8.new: unknown play mode %s; expected %s ' ..
            '(callbacks go in the onLoop field: anim.onLoop = fn)'):format(
            type(playMode) == 'string' and ('%q'):format(playMode) or tostring(playMode), MODE_LIST), 3)
    end

    local self = setmetatable({}, Animation)
    self.image    = image
    self.flippedH = false
    self.flippedV = false
    self.onLoop   = nil
    self.playMode = playMode
    -- Copied so later changes to the caller's list cannot desync the timing data.
    self.frames   = {}
    for i = 1, #frames do self.frames[i] = frames[i] end
    self._opts      = checkOptions(opts, #self.frames, 4)
    self._ticks     = self._opts.ticks or false
    self._speed     = 1
    self._baseDurations = parseDurations(durations, #self.frames, 4)
    if self._ticks then assertTickDurations(self._baseDurations, 4) end
    self._durations = self._opts.jitter
        and jittered(self._baseDurations, self._opts.jitter, self._opts.rng or math.random)
        or self._baseDurations

    self._data = self._opts.data
    if self._data then
        for frame, d in pairs(self._data) do
            if d.trim then
                self._trim = self._trim or {}
                self._trim[frame] = d.trim
            end
            if d.rotated then
                self._rotated = self._rotated or {}
                self._rotated[frame] = d.rotated
            end
            if d.transform then
                self._transforms = self._transforms or {}
                self._transforms[frame] = d.transform
            end
        end
    end

    initTiming(self)
    return self
end

-- Returns a new animation sharing the same immutable data (frames, durations,
-- sequence, intervals). Playback state starts fresh; flip, speed, onLoop and
-- registered callbacks are copied. Random-order and jittered animations get
-- their own order and durations.
function Animation:clone()
    local c = setmetatable({}, Animation)
    for k, v in pairs(self) do c[k] = v end
    if self._onFrame then
        c._onFrame = {}
        for frame, list in pairs(self._onFrame) do
            local copy = {}
            for i = 1, #list do copy[i] = list[i] end
            c._onFrame[frame] = copy
        end
    end
    if self._markers then
        c._markers = {}
        for i, m in ipairs(self._markers) do c._markers[i] = { t = m.t, fn = m.fn } end
    end
    if self._color then c._color = { self._color[1], self._color[2], self._color[3], self._color[4] } end
    if self._trail then
        local t = self._trail
        c._trail = { count = t.count, spacing = t.spacing, alpha = t.alpha, entries = {}, draws = 0 }
    end
    c._flash    = nil
    c._plain    = nil
    c._styled   = nil
    c._timer    = 0
    c._position = 1
    c._loops    = 0
    c._freeze   = 0
    c._started  = false
    c._released = false
    c.status    = 'playing'
    local o = self._opts
    if self.playMode == 'random' or o.jitter then
        if o.jitter then c._durations = jittered(c._baseDurations, o.jitter, o.rng or math.random) end
        applyTiming(c)
    else
        applyRegion(c)
    end
    c.currentFrame = c._seq[1]
    return c
end

for _, name in ipairs({ 'playback', 'timeline', 'events', 'frameinfo', 'render', 'state' }) do
    for method, fn in pairs(require(PKG .. '.' .. name).methods) do Animation[method] = fn end
end

return { Animation = Animation, build = build }
end

__modules['desAnim8.grid'] = function(...)
-- Spritesheet grids: quad lists addressed by column and row.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local assertPositiveInteger, assertNonNegativeInteger, parseRange = util.assertPositiveInteger, util.assertNonNegativeInteger, util.parseRange

-- The public table, handed over by _bind(); newGrid reads maxImageSize from it.
local root

local Grid = {}
Grid.__index = Grid

-- Advisory limit for constrained targets (PSP textures are at most 512x512).
-- nil disables the check; set it before creating grids.
local sizeWarned = false

-- newGrid(frameWidth, frameHeight, imageWidth, imageHeight [, left, top, border, inset])
-- border: pixel gap around every frame in the spritesheet (default 0). Like
-- anim8, one border precedes the first frame as well as separating frames.
-- inset: pixels trimmed from every side of each frame (default 0, may be
-- fractional) so linear filtering cannot bleed in a neighbouring frame.
local function newGrid(frameWidth, frameHeight, imageWidth, imageHeight, left, top, border, inset)
    assertPositiveInteger(frameWidth,  'frameWidth',  3)
    assertPositiveInteger(frameHeight, 'frameHeight', 3)
    assertPositiveInteger(imageWidth,  'imageWidth',  3)
    assertPositiveInteger(imageHeight, 'imageHeight', 3)
    left, top, border, inset = left or 0, top or 0, border or 0, inset or 0
    assertNonNegativeInteger(left,   'left',   3)
    assertNonNegativeInteger(top,    'top',    3)
    assertNonNegativeInteger(border, 'border', 3)
    if type(inset) ~= 'number' or not (inset >= 0) or inset * 2 >= math.min(frameWidth, frameHeight) then
        error(('inset must be a number in [0, %s), got %s'):format(
            tostring(math.min(frameWidth, frameHeight) / 2), tostring(inset)), 2)
    end
    local limit = root and root.maxImageSize
    if limit and not sizeWarned and (imageWidth > limit or imageHeight > limit) then
        sizeWarned = true
        print(('desAnim8: %sx%s image exceeds maxImageSize %s; split the sheet for this target'):format(
            tostring(imageWidth), tostring(imageHeight), tostring(limit)))
    end
    return setmetatable({
        frameWidth  = frameWidth,
        frameHeight = frameHeight,
        imageWidth  = imageWidth,
        imageHeight = imageHeight,
        left        = left,
        top         = top,
        border      = border,
        inset       = inset,
        _cache      = {},
        cols        = math.max(0, math.floor((imageWidth  - left - border) / (frameWidth  + border))),
        rows        = math.max(0, math.floor((imageHeight - top  - border) / (frameHeight + border))),
    }, Grid)
end

-- getFrames(colRange, rowRange [, colRange, rowRange ...])
-- Each pair selects a rectangle of frames in row-major order.
-- Returns a list of love.graphics.newQuad objects. Identical calls reuse the
-- quads built the first time (each call still gets its own list); see
-- Grid:clearCache.
function Grid:getFrames(...)
    local count = select('#', ...)
    local args  = { ... }
    local parts = {}
    for i = 1, count do parts[i] = tostring(args[i]) end
    local key = table.concat(parts, '|')
    local cached = self._cache[key]
    if cached then
        local copy = {}
        for i = 1, #cached do copy[i] = cached[i] end
        return copy
    end

    local frames = {}
    local fw, fh, bw = self.frameWidth, self.frameHeight, self.border
    local iw, ih     = self.imageWidth, self.imageHeight
    local inset      = self.inset
    local i = 1
    while i <= count do
        local cmin, cmax, cstep = parseRange(args[i],     self.cols, 3, 'column')
        local rmin, rmax, rstep = parseRange(args[i + 1], self.rows, 3, 'row')
        i = i + 2
        for row = rmin, rmax, rstep do
            for col = cmin, cmax, cstep do
                local x = self.left + (col - 1) * (fw + bw) + bw
                local y = self.top  + (row - 1) * (fh + bw) + bw
                frames[#frames + 1] = love.graphics.newQuad(
                    x + inset, y + inset, fw - 2 * inset, fh - 2 * inset, iw, ih)
            end
        end
    end
    if #frames == 0 then error('getFrames: no frames selected', 2) end
    local copy = {}
    for n = 1, #frames do copy[n] = frames[n] end
    self._cache[key] = copy
    return frames
end

-- Drops the memoized quad lists.
function Grid:clearCache()
    self._cache = {}
end

Grid.__call = Grid.getFrames

-- Like newGrid, reading the sheet size from the image.
local function newGridFromImage(image, frameWidth, frameHeight, left, top, border, inset)
    if image == nil or type(image.getDimensions) ~= 'function' then
        error('newGridFromImage: image must be an Image (it needs getDimensions)', 2)
    end
    local iw, ih = image:getDimensions()
    return newGrid(frameWidth, frameHeight, iw, ih, left, top, border, inset)
end

return {
    newGrid          = newGrid,
    newGridFromImage = newGridFromImage,
    _bind            = function(publicTable) root = publicTable end,
}
end

__modules['desAnim8.constructors'] = function(...)
-- desAnim8.new, newAnimation and newAnimationFromQuads.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local build = require(PKG .. '.animation').build
local assertPositiveInteger = util.assertPositiveInteger

local USAGE = 'desAnim8.new: expected (image, frames, durations [, playMode]) or the legacy ' ..
    '(image, frameWidth, frameHeight, numFrames, frameDuration, imageWidth, imageHeight [, playMode]); ' ..
    'for an animation without an image use desAnim8.newAnimation(frames, durations [, playMode])'

-- Legacy single-row form. Returns the frame list, durations and play mode.
-- Called from desAnim8.new, so the user's call is 3 frames up (4 from a helper).
local function legacyArgs(...)
    local fw, fh, n, dur, iw, ih, mode = ...
    if type(fw) ~= 'number' or select('#', ...) < 3 then error(USAGE, 3) end
    assertPositiveInteger(fw, 'frameWidth',  4)
    assertPositiveInteger(fh, 'frameHeight', 4)
    assertPositiveInteger(n,  'numFrames',   4)
    assertPositiveInteger(iw, 'imageWidth',  4)
    assertPositiveInteger(ih, 'imageHeight', 4)
    local frames = {}
    for i = 0, n - 1 do
        frames[#frames + 1] = love.graphics.newQuad(i * fw, 0, fw, fh, iw, ih)
    end
    return frames, dur, mode
end

-- New API:    new(image, frames, durations [, playMode [, opts]])
--             frames is a list of Quads, typically from Grid:getFrames()
-- Legacy API: new(image, frameWidth, frameHeight, numFrames, frameDuration, imageWidth, imageHeight [, playMode])
-- image may be nil: the image is then supplied at draw time (see newAnimation
-- and :draw), so one animation can be reused across several images and the
-- library never has to hold a backend's image handle.
local function new(image, ...)
    local frames, durations, playMode, opts
    if type((...)) == 'table' then
        frames, durations, playMode, opts = ...
    else
        frames, durations, playMode = legacyArgs(...)
    end
    local anim = build(image, frames, durations, playMode, opts)
    return anim
end

-- Image-less constructor. Equivalent to new(nil, frames, durations, playMode);
-- the image is passed to :draw at render time.
local function newAnimation(frames, durations, playMode, opts)
    local anim = build(nil, frames, durations, playMode, opts)
    return anim
end

-- Same as new(image, frames, durations, playMode), named for hand-made quad
-- lists (non-grid atlases, cropped regions).
local function newAnimationFromQuads(image, quads, durations, playMode, opts)
    local anim = build(image, quads, durations, playMode, opts)
    return anim
end

return {
    new                   = new,
    newAnimation          = newAnimation,
    newAnimationFromQuads = newAnimationFromQuads,
}
end

__modules['desAnim8.atlas'] = function(...)
-- Atlas adapters and the Aseprite importer. Nothing here reads files or decodes
-- JSON: callers pass decoded tables (or a decoder callback).
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local build = require(PKG .. '.animation').build
local assertPositiveInteger = util.assertPositiveInteger

-- Frame records are the common shape every adapter produces:
--   { x, y, w, h, trimX, trimY, sourceW, sourceH, name, duration, rotated }
-- x, y, w, h are the rectangle as stored in the image: for a rotated frame its
-- width and height are swapped. trim and source sizes describe the upright sprite.
-- rotated: true or 'cw' (stored turned 90 degrees clockwise, as TexturePacker,
-- Phaser and Starling do) or 'ccw' (counter-clockwise).
-- (trim and source fields default to "untrimmed"; duration is in seconds).

-- Returns quads, data (for the `data` constructor option) and, when every record
-- has one, a durations list.
local function newFramesFromRecords(records, imageWidth, imageHeight)
    if type(records) ~= 'table' or #records == 0 then
        error('newFramesFromRecords: records must be a non-empty list', 2)
    end
    assertPositiveInteger(imageWidth,  'imageWidth',  3)
    assertPositiveInteger(imageHeight, 'imageHeight', 3)
    local quads, data, durations, haveDurations = {}, {}, {}, true
    for i, rec in ipairs(records) do
        for _, key in ipairs({ 'x', 'y', 'w', 'h' }) do
            if type(rec[key]) ~= 'number' then
                error(('newFramesFromRecords: record %d needs a numeric %s'):format(i, key), 2)
            end
        end
        quads[i] = love.graphics.newQuad(rec.x, rec.y, rec.w, rec.h, imageWidth, imageHeight)
        local d = {}
        if rec.name ~= nil then d.name = rec.name end
        local tx, ty = rec.trimX or 0, rec.trimY or 0
        local sw, sh = rec.sourceW or rec.w, rec.sourceH or rec.h
        if tx ~= 0 or ty ~= 0 or sw ~= rec.w or sh ~= rec.h then
            d.trim = { x = tx, y = ty, w = sw, h = sh }
        end
        local rotated = rec.rotated
        if rotated == true or rotated == 'cw' then
            d.rotated = 'cw'
        elseif rotated == 'ccw' then
            d.rotated = 'ccw'
        elseif rotated ~= nil and rotated ~= false then
            error(('newFramesFromRecords: record %d has an invalid rotated value %s (use true, "cw" or "ccw")'):format(
                i, tostring(rotated)), 2)
        end
        if next(d) ~= nil then data[i] = d end
        durations[i] = rec.duration
        if rec.duration == nil then haveDurations = false end
    end
    return quads, data, haveDurations and durations or nil
end

local atlas = {}

-- Digit runs compare as numbers, so "hero 10" sorts after "hero 9".
local function naturalLess(a, b)
    local ia, ib = 1, 1
    while ia <= #a and ib <= #b do
        local da, db = a:match('^%d+', ia), b:match('^%d+', ib)
        if da and db then
            local na, nb = tonumber(da), tonumber(db)
            if na ~= nb then return na < nb end
            ia, ib = ia + #da, ib + #db
        else
            local ca, cb = a:sub(ia, ia), b:sub(ib, ib)
            if ca ~= cb then return ca < cb end
            ia, ib = ia + 1, ib + 1
        end
    end
    local restA, restB = #a - ia, #b - ib
    if restA ~= restB then return restA < restB end
    return a < b
end

-- The frames of an export as a list, plus the names when it is the hash form
-- (JSON Hash). A decoded hash has lost the file order, so frames sort by name
-- (the `filename` field, else the key), which matches the default naming of
-- Aseprite and TexturePacker. `level` is relative to the caller.
local function frameList(frames, who, level)
    if frames[1] ~= nil then return frames, nil end
    local entries = {}
    for key, f in pairs(frames) do
        if type(key) ~= 'string' then
            error(who .. ': a hash-form export needs string keys, got ' .. type(key), level + 1)
        end
        entries[#entries + 1] = { name = type(f) == 'table' and f.filename or key, key = key, f = f }
    end
    if #entries == 0 then error(who .. ': the export has no frames', level + 1) end
    table.sort(entries, function(a, b)
        if a.name ~= b.name then return naturalLess(a.name, b.name) end
        return a.key < b.key
    end)
    local list, names = {}, {}
    for i, e in ipairs(entries) do list[i], names[i] = e.f, e.name end
    return list, names
end

-- TexturePacker "JSON (Array)" export, already decoded. Returns records, the
-- image width and the image height (from meta.size, when present).
function atlas.fromTexturePacker(decoded)
    if type(decoded) ~= 'table' or type(decoded.frames) ~= 'table' then
        error('fromTexturePacker: expected a decoded export table with a frames list', 2)
    end
    local frames, names = frameList(decoded.frames, 'fromTexturePacker', 2)
    local records = {}
    for i, f in ipairs(frames) do
        local fr, src, size = f.frame, f.spriteSourceSize, f.sourceSize
        if type(fr) ~= 'table' then
            error(('fromTexturePacker: frame %s has no frame rectangle'):format(names and ('%q'):format(names[i]) or i), 2)
        end
        records[i] = {
            x = fr.x, y = fr.y, w = fr.w, h = fr.h,
            trimX = src and src.x or 0, trimY = src and src.y or 0,
            sourceW = size and size.w or fr.w, sourceH = size and size.h or fr.h,
            name = names and names[i] or f.filename, rotated = f.rotated,
            duration = f.duration and f.duration / 1000 or nil,
        }
    end
    local size = decoded.meta and decoded.meta.size
    return records, size and size.w, size and size.h
end

-- Starling / Sparrow sub-textures: a list of attribute tables (as produced by
-- any XML decoder) with x, y, width, height and optional frameX, frameY,
-- frameWidth, frameHeight. frameX and frameY are negative trim offsets.
function atlas.fromStarling(list)
    if type(list) ~= 'table' or list[1] == nil then
        error('fromStarling: expected a non-empty list of attribute tables', 2)
    end
    local records = {}
    for i, e in ipairs(list) do
        if e.rotated == true or e.rotated == 'true' then
            error(('fromStarling: entry %d is rotated; export the atlas without rotation'):format(i), 2)
        end
        records[i] = {
            x = e.x, y = e.y, w = e.width, h = e.height,
            trimX = -(e.frameX or 0), trimY = -(e.frameY or 0),
            sourceW = e.frameWidth or e.width, sourceH = e.frameHeight or e.height,
            name = e.name,
        }
    end
    return records
end

-- Aseprite "Array" export with frame tags, already decoded. Returns records
-- (durations in seconds), image width, image height, tags (1-based from/to) and
-- the slice list.
local function parseAseprite(decoded, level)
    if type(decoded) ~= 'table' or type(decoded.frames) ~= 'table' then
        error('fromAseprite: expected a decoded export table with a frames list', level)
    end
    local frames, names = frameList(decoded.frames, 'fromAseprite', level)
    local records = {}
    for i, f in ipairs(frames) do
        local fr, src, size = f.frame, f.spriteSourceSize, f.sourceSize
        if type(fr) ~= 'table' then
            error(('fromAseprite: frame %s has no frame rectangle'):format(names and ('%q'):format(names[i]) or i), level)
        end
        records[i] = {
            x = fr.x, y = fr.y, w = fr.w, h = fr.h,
            trimX = src and src.x or 0, trimY = src and src.y or 0,
            sourceW = size and size.w or fr.w, sourceH = size and size.h or fr.h,
            name = names and names[i] or f.filename, rotated = f.rotated,
            duration = (f.duration or 100) / 1000,
        }
    end
    local meta = decoded.meta or {}
    local tags = {}
    for i, t in ipairs(meta.frameTags or {}) do
        -- Aseprite writes `repeat` as a string; 0 or absent means forever.
        local count = t['repeat']
        if count ~= nil then
            count = tonumber(count)
            if count == nil or count < 0 or count ~= math.floor(count) or count == math.huge then
                error(('fromAseprite: tag %q has an invalid repeat %s'):format(
                    tostring(t.name), tostring(t['repeat'])), level)
            end
            if count == 0 then count = nil end
        end
        tags[i] = { name = t.name, from = t.from + 1, to = t.to + 1, direction = t.direction or 'forward',
                    repeatCount = count }
    end
    return records, meta.size and meta.size.w, meta.size and meta.size.h, tags, meta.slices or {}
end

function atlas.fromAseprite(decoded)
    return parseAseprite(decoded, 3)
end

local ASEPRITE_DIRECTIONS = { forward = true, reverse = true, pingpong = true, pingpong_reverse = true }

-- newFromAseprite(source, image, tag [, opts])
-- source: decoded export table, or a JSON string together with opts.decode.
-- tag: tag name; nil takes every frame, forward. Frame order and play mode come
-- from the tag direction (opts.playMode overrides the mode). Slices become frame
-- data (a slice with a pivot also sets `pivot`). Other opts go to the constructor.
-- A tag `repeat` of 1 plays once; N > 1 parks at the end after N plays through an
-- `onLoop` hook (opts.playMode drops the limit).
-- The library never reads files or decodes JSON itself.
local function newFromAseprite(source, image, tag, opts)
    local ctor = {}
    local decode, playMode
    for k, v in pairs(opts or {}) do
        if k == 'decode' then decode = v
        elseif k == 'playMode' then playMode = v
        else ctor[k] = v end
    end
    if ctor.data ~= nil then error('newFromAseprite: build the data from the export; opts.data is not accepted', 2) end
    local decoded = source
    if type(source) == 'string' then
        if type(decode) ~= 'function' then
            error('newFromAseprite: a JSON string needs opts.decode = function(text) returning a table', 2)
        end
        decoded = decode(source)
    elseif type(source) ~= 'table' then
        error('newFromAseprite: source must be a decoded export table or a JSON string', 2)
    end

    local records, iw, ih, tags, slices = parseAseprite(decoded, 3)
    if not (iw and ih) then
        if image ~= nil and type(image.getDimensions) == 'function' then
            iw, ih = image:getDimensions()
        else
            error('newFromAseprite: the export has no meta.size; pass the image so its size can be read', 2)
        end
    end

    local from, to, direction, repeatCount = 1, #records, 'forward', nil
    if tag ~= nil then
        local found
        for _, t in ipairs(tags) do
            if t.name == tag then found = t; break end
        end
        if not found then
            local names = {}
            for i, t in ipairs(tags) do names[i] = t.name end
            error(('newFromAseprite: no tag %q; the export has: %s'):format(
                tostring(tag), #names > 0 and table.concat(names, ', ') or '(none)'), 2)
        end
        from, to, direction, repeatCount = found.from, found.to, found.direction, found.repeatCount
        if from < 1 or to > #records or from > to then
            error(('newFromAseprite: tag %q has an invalid frame range'):format(tostring(tag)), 2)
        end
    end
    if not ASEPRITE_DIRECTIONS[direction] then
        error(('newFromAseprite: unknown tag direction %q'):format(tostring(direction)), 2)
    end

    local reverse = direction == 'reverse' or direction == 'pingpong_reverse'
    local order, subset = {}, {}
    for i = from, to do order[#order + 1] = i end
    if reverse then
        for i = 1, math.floor(#order / 2) do
            order[i], order[#order - i + 1] = order[#order - i + 1], order[i]
        end
    end
    for k, i in ipairs(order) do subset[k] = records[i] end

    local quads, data, durations = newFramesFromRecords(subset, iw, ih)
    for k, i in ipairs(order) do
        local absolute = i - 1
        for _, slice in ipairs(slices) do
            local key
            for _, candidate in ipairs(slice.keys or {}) do
                if candidate.frame <= absolute and (key == nil or candidate.frame > key.frame) then key = candidate end
            end
            if key then
                data[k] = data[k] or {}
                data[k][slice.name] = key.bounds
                if key.pivot and not data[k].pivot then data[k].pivot = key.pivot end
            end
        end
    end
    ctor.data = next(data) ~= nil and data or nil
    local pingpong = direction == 'pingpong' or direction == 'pingpong_reverse'
    local mode = playMode
    if not mode then
        if repeatCount == 1 then mode = pingpong and 'bounceOnce' or 'once'
        else mode = pingpong and 'bounce' or 'loop' end
    end
    local anim = build(image, quads, durations, mode, ctor)
    if repeatCount and repeatCount > 1 and not playMode then
        anim.onLoop = function(a)
            if a:getLoopCount() >= repeatCount then a:pauseAtEnd() end
        end
    end
    return anim
end

return {
    newFramesFromRecords = newFramesFromRecords,
    newFromAseprite      = newFromAseprite,
    atlas                = atlas,
    _parseAseprite       = parseAseprite,
}
end

__modules['desAnim8.sheet'] = function(...)
-- Tools that analyse a spritesheet's pixels. They take an ImageData-like object
-- (anything with getDimensions and getPixel) supplied by the caller.

-- Tight opaque rectangle of every quad, relative to the quad's top-left corner
-- ({ x = 0, y = 0, w = 0, h = 0 } for an empty frame). `imageData` is anything
-- with getPixel(x, y) -> r, g, b, a; pixels with alpha above `threshold` (default 0)
-- count as opaque.
local function scanBounds(quads, imageData, threshold)
    threshold = threshold or 0
    local out = {}
    for i, quad in ipairs(quads) do
        local qx, qy, qw, qh = quad:getViewport()
        qx, qy, qw, qh = math.floor(qx), math.floor(qy), math.floor(qw), math.floor(qh)
        local minX, minY, maxX, maxY = qw, qh, -1, -1
        for y = 0, qh - 1 do
            for x = 0, qw - 1 do
                local _, _, _, a = imageData:getPixel(qx + x, qy + y)
                if a > threshold then
                    if x < minX then minX = x end
                    if x > maxX then maxX = x end
                    if y < minY then minY = y end
                    if y > maxY then maxY = y end
                end
            end
        end
        out[i] = maxX < 0 and { x = 0, y = 0, w = 0, h = 0 }
            or { x = minX, y = minY, w = maxX - minX + 1, h = maxY - minY + 1 }
    end
    return out
end

-- Turns { name = listPerFrame } into the frame-indexed table the `data` option takes.
local function dataFromLists(lists)
    local data = {}
    for name, list in pairs(lists) do
        for i, value in pairs(list) do
            data[i] = data[i] or {}
            data[i][name] = value
        end
    end
    return data
end

-- Finds the opaque regions of an image (4-connected) and returns their bounding
-- rectangles { x, y, w, h } in row-major order, for sheets without a regular grid.
-- opts: threshold (alpha above it is opaque, default 0), mergeGap (join regions at
-- most this many empty pixels apart, default: no merging), minSize (drop regions
-- narrower or shorter than this).
local function sliceByAlpha(imageData, opts)
    opts = opts or {}
    local threshold = opts.threshold or 0
    local w, h = imageData:getDimensions()
    local opaque = {}
    for y = 0, h - 1 do
        for x = 0, w - 1 do
            local _, _, _, a = imageData:getPixel(x, y)
            opaque[y * w + x] = a > threshold
        end
    end

    local boxes = {}
    for y0 = 0, h - 1 do
        for x0 = 0, w - 1 do
            if opaque[y0 * w + x0] then
                local minX, maxX, minY, maxY = x0, x0, y0, y0
                local stack, top = { y0 * w + x0 }, 1
                opaque[y0 * w + x0] = false
                while top > 0 do
                    local idx = stack[top]
                    top = top - 1
                    local x, y = idx % w, math.floor(idx / w)
                    if x < minX then minX = x end
                    if x > maxX then maxX = x end
                    if y < minY then minY = y end
                    if y > maxY then maxY = y end
                    local n1, n2, n3, n4 = idx - 1, idx + 1, idx - w, idx + w
                    if x > 0 and opaque[n1] then opaque[n1] = false; top = top + 1; stack[top] = n1 end
                    if x < w - 1 and opaque[n2] then opaque[n2] = false; top = top + 1; stack[top] = n2 end
                    if y > 0 and opaque[n3] then opaque[n3] = false; top = top + 1; stack[top] = n3 end
                    if y < h - 1 and opaque[n4] then opaque[n4] = false; top = top + 1; stack[top] = n4 end
                end
                boxes[#boxes + 1] = { minX, minY, maxX, maxY }
            end
        end
    end

    local gap = opts.mergeGap
    if gap and #boxes > 1 then
        local merged = true
        while merged do
            merged = false
            for i = 1, #boxes do
                for j = i + 1, #boxes do
                    local a, b = boxes[i], boxes[j]
                    local dx = math.max(b[1] - a[3] - 1, a[1] - b[3] - 1, 0)
                    local dy = math.max(b[2] - a[4] - 1, a[2] - b[4] - 1, 0)
                    if a and b and dx <= gap and dy <= gap then
                        a[1], a[2] = math.min(a[1], b[1]), math.min(a[2], b[2])
                        a[3], a[4] = math.max(a[3], b[3]), math.max(a[4], b[4])
                        table.remove(boxes, j)
                        merged = true
                        break
                    end
                end
                if merged then break end
            end
        end
    end

    local rects = {}
    local minSize = opts.minSize or 1
    for _, b in ipairs(boxes) do
        local rw, rh = b[3] - b[1] + 1, b[4] - b[2] + 1
        if rw >= minSize and rh >= minSize then rects[#rects + 1] = { x = b[1], y = b[2], w = rw, h = rh } end
    end

    table.sort(rects, function(p, q)
        if p.y ~= q.y then return p.y < q.y end
        return p.x < q.x
    end)
    local ordered, row, ref = {}, nil, nil
    for _, r in ipairs(rects) do
        if ref and r.y < ref.y + ref.h then
            row[#row + 1] = r
        else
            if row then
                table.sort(row, function(p, q) return p.x < q.x end)
                for _, e in ipairs(row) do ordered[#ordered + 1] = e end
            end
            row, ref = { r }, r
        end
    end
    if row then
        table.sort(row, function(p, q) return p.x < q.x end)
        for _, e in ipairs(row) do ordered[#ordered + 1] = e end
    end
    return ordered
end

-- Quads for a list of { x, y, w, h } rectangles (for example from sliceByAlpha).
local function newQuadsFromRects(rects, imageWidth, imageHeight)
    local quads = {}
    for i, r in ipairs(rects) do
        quads[i] = love.graphics.newQuad(r.x, r.y, r.w, r.h, imageWidth, imageHeight)
    end
    return quads
end

return {
    scanBounds         = scanBounds,
    dataFromLists      = dataFromLists,
    sliceByAlpha       = sliceByAlpha,
    newQuadsFromRects  = newQuadsFromRects,
}
end

__modules['desAnim8.set'] = function(...)
-- Named clips: a Set plays one animation at a time and switches between them.
local PKG = (...):match('^(.*)%.[^.]*$')
local Animation = require(PKG .. '.animation').Animation
local atlas = require(PKG .. '.atlas')
local newFromAseprite, parseAseprite = atlas.newFromAseprite, atlas._parseAseprite

local Set = {}
Set.__index = Set

-- newSet(clips [, initial])
-- clips: { name = animation, ... }. `initial` defaults to the first name in
-- alphabetical order. Playback controls act on the current clip; the style setters
-- (setColor, setShader, ...) apply to every clip. Flip state follows the sprite
-- from clip to clip.
local function newSet(clips, initial)
    if type(clips) ~= 'table' or next(clips) == nil then
        error('newSet: clips must be a non-empty table of name -> animation', 2)
    end
    local self = setmetatable({ _clips = {} }, Set)
    local first
    for name, anim in pairs(clips) do
        if getmetatable(anim) ~= Animation then
            error(('newSet: clip %q is not an animation'):format(tostring(name)), 2)
        end
        self._clips[name] = anim
        if first == nil or tostring(name) < tostring(first) then first = name end
    end
    if initial == nil then initial = first end
    if not self._clips[initial] then
        error(('newSet: unknown clip %q'):format(tostring(initial)), 2)
    end
    self._name, self._cur = initial, self._clips[initial]
    return self
end

-- Switches clip (the new one starts over unless opts.keepPhase carries the
-- current phase across; opts.restart replays the clip that is already current).
-- Clears any queued clip and calls set.onChange(set, from, to) on a change.
function Set:play(name, opts)
    local nextClip = self._clips[name]
    if not nextClip then error(('play: unknown clip %q'):format(tostring(name)), 2) end
    self._queued = nil
    local restart = opts and opts.restart
    if nextClip == self._cur and not restart then return self end
    local prev, prevName = self._cur, self._name
    nextClip.flippedH, nextClip.flippedV = prev.flippedH, prev.flippedV
    local phase = opts and opts.keepPhase and prev:getPhase()
    nextClip:reset()
    if phase then nextClip:setPhase(phase) end
    self._cur, self._name = nextClip, name
    if prevName ~= name and self.onChange then self.onChange(self, prevName, name) end
    return self
end

-- Plays `name` when the current clip finishes (once modes) or completes its
-- current loop (looping modes).
function Set:queue(name)
    if not self._clips[name] then error(('queue: unknown clip %q'):format(tostring(name)), 2) end
    self._queued = name
    return self
end

-- Declares that `name` hands over to `nextName` whenever it finishes (once modes)
-- or completes a loop, unless another clip was queued. nil clears the rule.
function Set:setNext(name, nextName)
    if not self._clips[name] then error(('setNext: unknown clip %q'):format(tostring(name)), 2) end
    if nextName ~= nil and not self._clips[nextName] then
        error(('setNext: unknown clip %q'):format(tostring(nextName)), 2)
    end
    self._next = self._next or {}
    self._next[name] = nextName
    return self
end

function Set:update(dt)
    local clip = self._cur
    local loops = clip._loops
    clip:update(dt)
    local queued = self._queued or (self._next and self._next[self._name])
    if queued and (clip._loops > loops or clip:isFinished()) then self:play(queued) end
end

-- Returns the current animation and its name.
function Set:getCurrent()
    return self._cur, self._name
end

function Set:getClip(name)
    return self._clips[name]
end

local function passThrough(clip, set, ...)
    if select('#', ...) == 1 and (...) == clip then return set end
    return ...
end

for _, name in ipairs({
    'draw', 'getFrameInfo', 'pause', 'resume', 'pauseAtEnd', 'pauseAtStart', 'stop', 'reset', 'gotoFrame',
    'isPlaying', 'isPaused', 'getCurrentFrame', 'getCurrentFrameNumber', 'getDimensions', 'getFrameCount',
    'getDuration', 'getPlayMode', 'getRemainingTime', 'getPhase', 'setPhase', 'getLoopCount', 'isFinished',
    'flipH', 'flipV', 'setFlipH', 'setFlipV', 'faceTowards', 'setSpeed', 'getSpeed', 'fitDuration', 'freeze',
    'flash', 'getFrameData', 'getWorldRect', 'drawBounds', 'addToBatch', 'setInBatch', 'wait',
    'getFrameProgress',
}) do
    Set[name] = function(self, ...)
        local clip = self._cur
        return passThrough(clip, self, clip[name](clip, ...))
    end
end

for _, name in ipairs({
    'setColor', 'setAlpha', 'setBlendMode', 'setShader', 'setPixelSnap', 'setDefaultFacing', 'setAutoPivot',
}) do
    Set[name] = function(self, ...)
        for _, clip in pairs(self._clips) do clip[name](clip, ...) end
        return self
    end
end

-- One clip per frame tag of an Aseprite export (decoded table, or a JSON string
-- with opts.decode). opts.initial names the starting clip (default: the first
-- tag in the file); the other opts go to newFromAseprite.
local function newSetFromAseprite(source, image, opts)
    local clipOpts, initial, decoded = {}, nil, source
    for k, v in pairs(opts or {}) do
        if k == 'initial' then initial = v else clipOpts[k] = v end
    end
    if type(source) == 'string' then
        if type(clipOpts.decode) ~= 'function' then
            error('newSetFromAseprite: a JSON string needs opts.decode = function(text) returning a table', 2)
        end
        decoded = clipOpts.decode(source)
        clipOpts.decode = nil
    end
    local _, _, _, tags = parseAseprite(decoded, 3)
    local clips = {}
    if #tags == 0 then
        clips.default = newFromAseprite(decoded, image, nil, clipOpts)
        initial = initial or 'default'
    else
        for _, tag in ipairs(tags) do
            clips[tag.name] = newFromAseprite(decoded, image, tag.name, clipOpts)
        end
        initial = initial or tags[1].name
    end
    return newSet(clips, initial)
end

return {
    newSet             = newSet,
    newSetFromAseprite = newSetFromAseprite,
}
end

__modules['desAnim8.composite'] = function(...)
-- Layered sprites that share one clock.
local PKG = (...):match('^(.*)%.[^.]*$')
local flipFor = require(PKG .. '.util').flipFor

local Composite = {}
Composite.__index = Composite

-- newComposite(layers)
-- layers: { { anim = a }, { anim = b, dx = 4, dy = -2, hidden = false, image = img }, ... }
-- Animations or sets. The first layer is the clock; the others follow its phase
-- (and so do not fire their own events). dx and dy shift a layer in sprite
-- pixels and are mirrored when the composite is flipped. `image` is only needed
-- for image-less animations.
local function newComposite(layers)
    if type(layers) ~= 'table' or #layers == 0 then
        error('newComposite: layers must be a non-empty list of { anim = ... }', 2)
    end
    local self = setmetatable({ _layers = {}, flippedH = false, flippedV = false }, Composite)
    for i, l in ipairs(layers) do
        local anim = l.anim
        if type(anim) ~= 'table' or type(anim.getFrameInfo) ~= 'function' then
            error(('newComposite: layer %d needs an anim (an animation or a set)'):format(i), 2)
        end
        self._layers[i] = { anim = anim, dx = l.dx or 0, dy = l.dy or 0, hidden = l.hidden == true, image = l.image }
    end
    return self
end

function Composite:update(dt)
    local layers = self._layers
    local master = layers[1].anim
    master:update(dt)
    local phase = master:getPhase()
    for i = 2, #layers do layers[i].anim:setPhase(phase) end
end

function Composite:draw(x, y, r, sx, sy, ox, oy, kx, ky)
    for _, layer in ipairs(self._layers) do
        if not layer.hidden then
            local dx, dy = layer.dx, layer.dy
            if self.flippedH then dx = -dx end
            if self.flippedV then dy = -dy end
            local lox, loy = (ox or 0) - dx, (oy or 0) - dy
            if layer.image ~= nil then
                layer.anim:draw(layer.image, x, y, r, sx, sy, lox, loy, kx, ky)
            else
                layer.anim:draw(x, y, r, sx, sy, lox, loy, kx, ky)
            end
        end
    end
end

function Composite:getLayer(index)
    local layer = self._layers[index]
    return layer and layer.anim
end

function Composite:setHidden(index, hidden)
    local layer = self._layers[index]
    if not layer then error(('setHidden: no layer %s'):format(tostring(index)), 2) end
    layer.hidden = hidden == true
    return self
end

function Composite:setFlipH(flipped)
    self.flippedH = flipped
    for _, layer in ipairs(self._layers) do layer.anim:setFlipH(flipped) end
    return self
end

function Composite:setFlipV(flipped)
    self.flippedV = flipped
    for _, layer in ipairs(self._layers) do layer.anim:setFlipV(flipped) end
    return self
end

function Composite:flipH() return self:setFlipH(not self.flippedH) end
function Composite:flipV() return self:setFlipV(not self.flippedV) end

function Composite:faceTowards(dx)
    if type(dx) ~= 'number' or dx ~= dx then
        error(('faceTowards: dx must be a number, got %s'):format(tostring(dx)), 2)
    end
    if dx ~= 0 then self:setFlipH(flipFor(dx, self._layers[1].anim._facing or 1)) end
    return self
end

function Composite:setPhase(p)
    for _, layer in ipairs(self._layers) do layer.anim:setPhase(p) end
    return self
end

function Composite:getPhase()
    return self._layers[1].anim:getPhase()
end

function Composite:isPlaying()
    return self._layers[1].anim:isPlaying()
end

for _, name in ipairs({ 'pause', 'resume', 'reset', 'stop', 'pauseAtEnd', 'pauseAtStart' }) do
    Composite[name] = function(self)
        for _, layer in ipairs(self._layers) do layer.anim[name](layer.anim) end
        return self
    end
end

return { newComposite = newComposite }
end

__modules['desAnim8.batch'] = function(...)
-- Many entries of one animation definition, advanced together and drawn through
-- a single SpriteBatch.
local PKG = (...):match('^(.*)%.[^.]*$')
local util = require(PKG .. '.util')
local timing = require(PKG .. '.timing')
local build = require(PKG .. '.animation').build
local isInteger, seekIndex = util.isInteger, util.seekIndex
local PAUSE_AT_END, clock = timing.PAUSE_AT_END, timing.clock

local Batch = {}
Batch.__index = Batch

-- newBatch(image, frames, durations, playMode, capacity [, opts])
-- Thousands of entries that share one definition, advanced in a single call and
-- drawn through one SpriteBatch. A frame change rewrites only that sprite. Each
-- entry has a position, transform, flip, speed and phase; loop ranges, events
-- and the other per-animation features are not available here.
local function newBatch(image, frames, durations, playMode, capacity, opts)
    if not isInteger(capacity) or capacity < 1 then
        error(('newBatch: capacity must be a positive integer, got %s'):format(tostring(capacity)), 2)
    end
    local template = build(image, frames, durations, playMode, opts)
    local self = setmetatable({}, Batch)
    self._anim     = template
    self._batch    = love.graphics.newSpriteBatch(image, capacity)
    self._capacity = capacity
    self._count    = 0
    self._top      = 0
    self._free     = {}
    self._finish   = PAUSE_AT_END[template.playMode] or false
    self._timer, self._pos, self._speed, self._done, self._alive = {}, {}, {}, {}, {}
    self._flipH, self._flipV = {}, {}
    self._args = {}
    return self
end

local function batchWrite(self, id, isNew)
    local a, args = self._anim, self._args[id]
    a.currentFrame = a._seq[self._pos[id]]
    a._position    = self._pos[id]
    a._timer       = self._timer[id]
    a.flippedH, a.flippedV = self._flipH[id], self._flipV[id]
    local quad, x, y, r, sx, sy, ox, oy, kx, ky = a:getFrameInfo(
        args[1], args[2], args[3], args[4], args[5], args[6], args[7], args[8], args[9])
    if isNew then
        local got = self._batch:add(quad, x, y, r, sx, sy, ox, oy, kx, ky)
        assert(got == id, 'desAnim8 batch: sprite index out of step')
    else
        self._batch:set(id, quad, x, y, r, sx, sy, ox, oy, kx, ky)
    end
end

local function checkEntry(self, id, what)
    if not self._alive[id] then error(('%s: no entry %s'):format(what, tostring(id)), 3) end
end

-- Adds an entry drawn with the usual x, y, r, sx, sy, ox, oy, kx, ky; returns its id.
function Batch:add(x, y, r, sx, sy, ox, oy, kx, ky)
    if self._count >= self._capacity then
        error(('add: batch is full (capacity %d)'):format(self._capacity), 2)
    end
    local id = table.remove(self._free)
    local isNew = id == nil
    if isNew then
        self._top = self._top + 1
        id = self._top
    end
    self._alive[id], self._done[id] = true, false
    self._timer[id], self._pos[id], self._speed[id] = 0, 1, 1
    self._flipH[id], self._flipV[id] = false, false
    self._args[id] = { x, y, r, sx, sy, ox, oy, kx, ky }
    self._count = self._count + 1
    batchWrite(self, id, isNew)
    return id
end

-- Frees an entry; its sprite is hidden and the slot is reused by the next add.
function Batch:remove(id)
    checkEntry(self, id, 'remove')
    self._alive[id] = false
    self._free[#self._free + 1] = id
    self._count = self._count - 1
    self._batch:set(id, self._anim.frames[1], 0, 0, 0, 0, 0)
end

function Batch:clear()
    self._batch:clear()
    self._count, self._top, self._free = 0, 0, {}
    self._timer, self._pos, self._speed, self._done, self._alive = {}, {}, {}, {}, {}
    self._flipH, self._flipV, self._args = {}, {}, {}
end

function Batch:getCount()
    return self._count
end

function Batch:getFrame(id)
    checkEntry(self, id, 'getFrame')
    return self._anim._seq[self._pos[id]]
end

-- Moves or retransforms an entry.
function Batch:set(id, x, y, r, sx, sy, ox, oy, kx, ky)
    checkEntry(self, id, 'set')
    self._args[id] = { x, y, r, sx, sy, ox, oy, kx, ky }
    batchWrite(self, id, false)
end

function Batch:setFlip(id, horizontal, vertical)
    checkEntry(self, id, 'setFlip')
    self._flipH[id], self._flipV[id] = horizontal == true, vertical == true
    batchWrite(self, id, false)
end

function Batch:setSpeed(id, rate)
    checkEntry(self, id, 'setSpeed')
    if type(rate) ~= 'number' or rate ~= rate or rate == math.huge or rate == -math.huge then
        error(('setSpeed: speed must be a finite number, got %s'):format(tostring(rate)), 2)
    end
    self._speed[id] = rate
end

local function batchPhase(self, id, p)
    local a = self._anim
    p = math.max(0, math.min(1, p))
    local timer = p * a._totalDuration
    self._timer[id] = timer
    self._done[id]  = false
    self._pos[id]   = timer >= a._totalDuration and #a._seq or seekIndex(a._intervals, timer)
end

function Batch:setPhase(id, p)
    checkEntry(self, id, 'setPhase')
    if type(p) ~= 'number' or p ~= p then error('setPhase: phase must be a number', 2) end
    batchPhase(self, id, p)
    batchWrite(self, id, false)
end

-- Gives every entry a random phase (keeps a crowd out of sync).
function Batch:randomizePhases(rng)
    rng = rng or math.random
    for id = 1, self._top do
        if self._alive[id] then
            batchPhase(self, id, rng())
            batchWrite(self, id, false)
        end
    end
end

function Batch:update(dt)
    if type(dt) ~= 'number' then
        error(('update: dt must be a number, got %s'):format(type(dt)), 2)
    end
    if not (dt > 0) or dt == math.huge then return end
    local a = self._anim
    local total, intervals, seq = a._totalDuration, a._intervals, a._seq
    local finish = self._finish
    local timers, positions, speeds, done = self._timer, self._pos, self._speed, self._done
    for id = 1, self._top do
        if self._alive[id] and not done[id] then
            local step = dt * speeds[id]
            step = step * clock.scale
            if step ~= 0 then
                local timer, oldPos = timers[id], positions[id]
                local newPos
                timer = timer + step
                if step > 0 then
                    if timer >= total then
                        if finish then
                            done[id], timer, newPos = true, total, #seq
                        else
                            timer = timer - total * math.floor(timer / total)
                        end
                    end
                elseif timer < 0 then
                    if finish then
                        done[id], timer, newPos = true, 0, 1
                    else
                        timer = timer + total * math.ceil((0 - timer) / total)
                    end
                end
                timers[id] = timer
                newPos = newPos or seekIndex(intervals, timer)
                positions[id] = newPos
                if newPos ~= oldPos then batchWrite(self, id, false) end
            end
        end
    end
end

function Batch:draw(...)
    love.graphics.draw(self._batch, ...)
end

return { newBatch = newBatch }
end

__modules['desAnim8.watcher'] = function(...)
-- Reload-on-change helper.

local Watcher = {}
Watcher.__index = Watcher

local function defaultStat(path)
    local info = love.filesystem.getInfo(path)
    return info and info.modtime
end

-- newWatcher(path, onChange [, statFn])
-- Call watcher:poll() now and then (once a second is plenty). The first poll only
-- records the file's modification time; later polls call onChange(path) when it
-- moves and return true. statFn(path) -> modification time or nil; the default
-- uses love.filesystem.getInfo.
local function newWatcher(path, onChange, statFn)
    if type(onChange) ~= 'function' then error('newWatcher: onChange must be a function', 2) end
    return setmetatable({ _path = path, _onChange = onChange, _stat = statFn or defaultStat }, Watcher)
end

function Watcher:poll()
    local modified = self._stat(self._path)
    if modified == nil then return false end
    if self._last == nil then
        self._last = modified
        return false
    end
    if modified ~= self._last then
        self._last = modified
        self._onChange(self._path)
        return true
    end
    return false
end

return { newWatcher = newWatcher }
end

__modules['desAnim8.shaders'] = function(...)
-- GLSL sources as plain strings. Public as desAnim8.shaders.

-- GLSL sources for Animation:setShader. They are plain strings, so nothing is
-- compiled until you call love.graphics.newShader(desAnim8.shaders.whiteFlash).
local shaders = {
    -- uniform float amount: 0 leaves the sprite alone, 1 paints it white.
    whiteFlash = [[
        uniform float amount;
        vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
            vec4 p = Texel(tex, uv) * color;
            return vec4(mix(p.rgb, vec3(1.0), amount), p.a);
        }
    ]],
    -- Sprites store a palette index in the red channel (0..1). `palette` holds one
    -- row of colors per swap; `row` (0-based) picks the row out of `rows`.
    paletteSwap = [[
        uniform Image palette;
        uniform float row;
        uniform float rows;
        vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
            vec4 p = Texel(tex, uv);
            vec4 mapped = Texel(palette, vec2(p.r, (row + 0.5) / rows));
            return vec4(mapped.rgb, p.a) * color;
        }
    ]],
    -- Draws `outlineColor` on transparent pixels next to opaque ones. `texel` is
    -- 1 / image size; leave a pixel of padding around frames in the sheet.
    outline = [[
        uniform vec2 texel;
        uniform vec4 outlineColor;
        vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
            vec4 p = Texel(tex, uv);
            float around = Texel(tex, uv + vec2(texel.x, 0.0)).a + Texel(tex, uv - vec2(texel.x, 0.0)).a
                         + Texel(tex, uv + vec2(0.0, texel.y)).a + Texel(tex, uv - vec2(0.0, texel.y)).a;
            if (p.a < 0.5 && around > 0.0) return outlineColor;
            return p * color;
        }
    ]],
}

return shaders
end

__modules['desAnim8'] = function(...)
-- desAnim8: sprite animation for LÖVE 11.5. This file is the entry point: it
-- assembles the public API from the modules in desAnim8/. Console targets without
-- a working require can use the single-file build in dist/ (see tools/bundle.lua).
local PKG = ... or 'desAnim8'

local desAnim8 = {
    _VERSION     = 'desAnim8 v1.0.0',
    _DESCRIPTION = 'An animation library for LÖVE 11.5 games',
    _URL         = 'https://github.com/legendaryredfox/desAnim8',
    _THANKS      = 'All thanks, recognition and incentives should go to https://github.com/kikito',
    _LICENSE     = [[
      MIT LICENSE

      Copyright (c) 2024 Legendary Redfox

      Permission is hereby granted, free of charge, to any person obtaining a
      copy of this software and associated documentation files (the
      "Software"), to deal in the Software without restriction, including
      without limitation the rights to use, copy, modify, merge, publish,
      distribute, sublicense, and/or sell copies of the Software, and to
      permit persons to whom the Software is furnished to do so, subject to
      the following conditions:

      The above copyright notice and this permission notice shall be included
      in all copies or substantial portions of the Software.

      THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS
      OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF
      MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT.
      IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY
      CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT,
      TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE
      SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.
    ]]
}

-- ── Helpers ───────────────────────────────────────────────────────────────────

local function load(name)
    return require(PKG .. '.' .. name)
end

-- Copies a module's public members into desAnim8; names starting with an
-- underscore are internal and stay behind.
local function merge(api)
    for name, value in pairs(api) do
        if name:sub(1, 1) ~= '_' then desAnim8[name] = value end
    end
end

local grid = load('grid')
grid._bind(desAnim8)      -- newGrid reads desAnim8.maxImageSize
merge(grid)

for _, name in ipairs({
    'constructors', 'atlas', 'sheet', 'set', 'composite', 'batch', 'watcher',
}) do
    merge(load(name))
end

local timing = load('timing')
desAnim8.setTimeScale = timing.setTimeScale
desAnim8.getTimeScale = timing.getTimeScale

desAnim8.debug   = load('debug')
desAnim8.shaders = load('shaders')

return desAnim8
end

return require('desAnim8')
